function _newRid() {
  try { return crypto.randomBytes(8).toString('hex'); } catch (_) {}
  return String(Date.now()) + '-' + Math.random().toString(16).slice(2);
}
function _safeJson(v) {
  try { return JSON.stringify(v); } catch (_) { return '"[unserializable]"'; }
}
function _reqUserRef(req) {
  try {
    const u = req?.usuario || null;
    const id = u?.id != null ? String(u.id) : '';
    const email = u?.email != null ? String(u.email) : '';
    const nome = u?.nome != null ? String(u.nome) : '';
    return { id, email, nome };
  } catch (_) { return { id: '', email: '', nome: '' }; }
}
function _logApiError(tag, req, err, extra) {
  try {
    const rid = req?._rid || '';
    const user = _reqUserRef(req);
    const line = [
      `[${tag}]`,
      rid ? `rid=${rid}` : '',
      req?.method ? `m=${req.method}` : '',
      req?.originalUrl ? `url=${req.originalUrl}` : '',
      (user.id || user.email || user.nome) ? `user=${_safeJson(user)}` : '',
    ].filter(Boolean).join(' ');
    console.error(line);
    if (extra) console.error(`[${tag}] extra:`, extra);
    if (err instanceof Error) console.error(`[${tag}] err:`, { name: err.name, message: err.message, stack: err.stack });
    else console.error(`[${tag}] err:`, err);
  } catch (_) {}
}

const _serverCache = {};
const _serverCacheTTL = {};
const SERVER_CACHE_TTL = 10 * 60 * 1000;
// Limpar cache ao iniciar
Object.keys(_serverCache).forEach(k => delete _serverCache[k]);
Object.keys(_serverCacheTTL).forEach(k => delete _serverCacheTTL[k]);

function cacheGet(key) {
  if (_serverCacheTTL[key] && Date.now() < _serverCacheTTL[key]) return _serverCache[key];
  return null;
}
function cacheSet(key, data, ttlMs) {
  _serverCache[key] = data;
  const ttl = Number(ttlMs);
  _serverCacheTTL[key] = Date.now() + (Number.isFinite(ttl) && ttl > 0 ? ttl : SERVER_CACHE_TTL);
}
function cacheClear(key) {
  delete _serverCache[key];
  delete _serverCacheTTL[key];
}
function cacheClearPrefix(prefix) {
  Object.keys(_serverCache).forEach((k) => {
    if (k.startsWith(prefix)) cacheClear(k);
  });
  Object.keys(_serverCacheTTL).forEach((k) => {
    if (k.startsWith(prefix)) cacheClear(k);
  });
}
function _clearOfsCaches() {
  try { cacheClearPrefix('ofs_'); } catch (_) {}
}
async function resolverEmpresaId(req) {
  const emailRaw = String(
    req?.user?.email ||
    req?.user?.username ||
    req?.usuario?.email ||
    req?.usuario?.username ||
    ''
  ).trim();
  if (!emailRaw || !supabase) return null;

  const exactCandidates = Array.from(new Set([
    emailRaw,
    emailRaw.toLowerCase(),
    emailRaw.toUpperCase(),
  ].filter(Boolean)));
  for (const candidate of exactCandidates) {
    try {
      const { data: usr1 } = await supabase
        .from('usuarios')
        .select('empresa_id')
        .eq('email', candidate)
        .maybeSingle();
      if (usr1?.empresa_id) return usr1.empresa_id;
    } catch (_) {}
  }

  const prefixo = String(emailRaw.split('@')[0] || '').trim().toLowerCase();
  if (!prefixo) return null;

  try {
    const { data: usr2 } = await supabase
      .from('usuarios')
      .select('empresa_id')
      .ilike('email', prefixo)
      .limit(1)
      .maybeSingle();
    if (usr2?.empresa_id) return usr2.empresa_id;
  } catch (_) {}

  try {
    const { data: usr3 } = await supabase
      .from('usuarios')
      .select('empresa_id')
      .ilike('email', prefixo + '%')
      .limit(1)
      .maybeSingle();
    if (usr3?.empresa_id) return usr3.empresa_id;
  } catch (_) {}

  try {
    const { data: emp } = await supabase
      .from('empresas')
      .select('id')
      .ilike('sigla', '%' + prefixo + '%')
      .limit(1)
      .maybeSingle();
    if (emp?.id) return emp.id;
  } catch (_) {}

  try {
    const { data: empPrimeira } = await supabase
      .from('empresas')
      .select('id')
      .limit(1)
      .maybeSingle();
    if (empPrimeira?.id) {
      console.debug('[resolverEmpresaId] fallback para primeira empresa:', empPrimeira.id);
      return empPrimeira.id;
    }
  } catch (_) {}

  return null;
}
if (Array.isArray(globalThis.__pendingCacheClearPrefixes) && globalThis.__pendingCacheClearPrefixes.length) {
  globalThis.__pendingCacheClearPrefixes.forEach((p) => {
    try { cacheClearPrefix(String(p || '')); } catch (_) {}
  });
  try { delete globalThis.__pendingCacheClearPrefixes; } catch (_) { globalThis.__pendingCacheClearPrefixes = null; }
}

function setNoCache(res, filePath) {
  try {
    if (filePath && String(filePath).endsWith(path.sep + 'sw.js')) {
      res.setHeader('Content-Type', 'application/javascript');
      res.setHeader('Cache-Control', 'no-cache');
      return;
    }
    if (filePath && String(filePath).endsWith(path.sep + 'manifest.json')) {
      res.setHeader('Content-Type', 'application/manifest+json');
      res.setHeader('Cache-Control', 'public, max-age=300');
      return;
    }
  } catch (_) {}
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
  res.setHeader('Surrogate-Control', 'no-store');
}

