app.post('/api/usuarios/avatar', authMiddleware, async (req, res) => {
  try {
    const uploadAv = multer({
      storage: multer.memoryStorage(),
      limits: { fileSize: 5 * 1024 * 1024 },
      fileFilter: function (_req, file, cb) {
        const mt = String(file?.mimetype || '').toLowerCase();
        if (mt.startsWith('image/')) return cb(null, true);
        return cb(new Error('Apenas imagens'));
      },
    });

    uploadAv.single('avatar')(req, res, async function (err) {
      try {
        if (err) {
          try { console.error('[avatar] multer error:', String(err.message || err)); } catch (_) {}
          return res.status(400).json({ ok: false, error: String(err.message || err) });
        }

        if (!req.file) {
          return res.status(400).json({ ok: false, error: 'Nenhum arquivo recebido' });
        }

        const userId = req.usuario?.id || req.usuario?.sub;
        if (!userId) return res.status(401).json({ ok: false, error: 'usuario nao identificado' });

        const mime = String(req.file.mimetype || 'image/jpeg');
        let ext = String((mime.split('/')[1] || 'jpg')).toLowerCase();
        if (ext === 'jpeg') ext = 'jpg';
        if (!/^[a-z0-9]+$/i.test(ext)) ext = 'jpg';
        const fileName = 'avatares/' + String(userId) + '.' + ext;

        const tryUpload = async (bucket) => {
          const b = String(bucket || '').trim();
          const { error: upErr } = await supabase.storage
            .from(b)
            .upload(fileName, req.file.buffer, { contentType: mime, upsert: true });
          if (upErr) throw upErr;
          const { data: urlData } = supabase.storage.from(b).getPublicUrl(fileName);
          const publicUrl = String(urlData?.publicUrl || '').trim();
          if (!publicUrl) throw new Error('Falha ao obter URL pública');
          return { publicUrl, bucket: b };
        };

        let publicUrl = '';
        let bucketUsed = 'chat-arquivos';
        try {
          const r1 = await tryUpload('chat-arquivos');
          publicUrl = r1.publicUrl;
          bucketUsed = r1.bucket;
        } catch (upErr) {
          const msg = String(upErr?.message || upErr || '');
          const bucketNotFound = msg.toLowerCase().includes('bucket') && msg.toLowerCase().includes('not');
          if (bucketNotFound) {
            try {
              await supabase.storage.createBucket('chat-arquivos', { public: true });
              const r2 = await tryUpload('chat-arquivos');
              publicUrl = r2.publicUrl;
              bucketUsed = r2.bucket;
            } catch (e2) {
              try {
                const r3 = await tryUpload('uploads');
                publicUrl = r3.publicUrl;
                bucketUsed = r3.bucket;
              } catch (e3) {
                return res.status(500).json({
                  ok: false,
                  error: 'Bucket não encontrado. Crie o bucket "chat-arquivos" no Supabase Storage (Public) ou use "uploads".',
                });
              }
            }
          } else {
            try {
              const r3 = await tryUpload('uploads');
              publicUrl = r3.publicUrl;
              bucketUsed = r3.bucket;
            } catch (e3) {
              return res.status(500).json({ ok: false, error: msg || 'Falha no upload' });
            }
          }
        }

        const avatarUrl = publicUrl + '?v=' + Date.now();

        const { error: dbErr } = await supabase
          .from('usuarios')
          .update({ avatar_url: avatarUrl })
          .eq('id', userId);

        if (dbErr) {
          try { console.error('[avatar] db error:', String(dbErr.message || dbErr)); } catch (_) {}
          return res.json({ ok: true, avatar_url: avatarUrl, bucket: bucketUsed, aviso: 'URL salva temporariamente' });
        }

        return res.json({ ok: true, avatar_url: avatarUrl, bucket: bucketUsed });
      } catch (e) {
        try { console.error('[avatar] inner catch:', String(e?.message || e)); } catch (_) {}
        return res.status(500).json({ ok: false, error: String(e?.message || e) });
      }
    });
  } catch (e) {
    try { console.error('[avatar] catch:', String(e?.message || e)); } catch (_) {}
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.post('/api/auth/refresh', async (req, res) => {
  try {
    const oldToken =
      _getTokenFromReq(req)
      || _normalizeTokenCandidate(req.body?.token || req.body?.access_token || req.body?.refresh_token || req.body?.refreshToken || '')
      || _normalizeTokenCandidate(req.headers['x-refresh-token'] || req.headers['x-refresh_token'] || '');
    if (!oldToken) {
      _clearAuthCookies(res);
      return res.status(401).json({ ok: false, error: 'token_missing', redirect: '/login' });
    }

    let payload = null;
    try {
      payload = jwt.verify(oldToken, JWT_SECRET, { ignoreExpiration: true });
    } catch (_) {
      try { payload = jwt.decode(oldToken); } catch (e) { payload = null; }
    }
    const uid = String(payload?.id || '').trim();
    if (!uid) {
      _clearAuthCookies(res);
      return res.status(401).json({ ok: false, error: 'token_invalid', redirect: '/login' });
    }

    const { data: dbUser, error } = await supabase
      .from('usuarios')
      .select('id,nome,email,perfil,permissoes,canais_chat,ativo,avatar_iniciais,avatar_cor')
      .eq('id', uid)
      .single();
    if (error || !dbUser) {
      _clearAuthCookies(res);
      return res.status(401).json({ ok: false, error: 'user_not_found', redirect: '/login' });
    }
    if (dbUser.ativo === false) {
      _clearAuthCookies(res);
      return res.status(401).json({ ok: false, error: 'user_inactive', redirect: '/login' });
    }

    let perms = dbUser.permissoes != null ? dbUser.permissoes : [];
    if (typeof perms === 'string') { try { perms = JSON.parse(perms); } catch (_) { perms = []; } }
    if (!Array.isArray(perms)) perms = [];
    const perfilNorm = String(dbUser.perfil || '').trim().toLowerCase();
    if ((perfilNorm === 'admin' || perfilNorm.includes('admin')) && !perms.includes('tudo')) perms = ['tudo', ...perms];

    const token = jwt.sign(
      { id: dbUser.id, nome: dbUser.nome, email: dbUser.email, perfil: dbUser.perfil, permissoes: perms },
      JWT_SECRET,
      { expiresIn: '30d' }
    );
    console.log('[TOKEN REFRESH] perfil:', dbUser.perfil, 'permissoes:', dbUser.permissoes);
    _setAuthCookies(res, token);
    return res.json({
      ok: true,
      token,
      access_token: token,
      refresh_token: token,
      token_type: 'Bearer',
      expires_in: AUTH_TOKEN_MAX_AGE_MS / 1000,
      usuario: {
        id: dbUser.id,
        nome: dbUser.nome,
        email: dbUser.email,
        perfil: dbUser.perfil,
        permissoes: perms,
        canais_chat: dbUser.canais_chat,
        avatar_iniciais: dbUser.avatar_iniciais || initialsFromName(dbUser.nome),
        avatar_cor: dbUser.avatar_cor || avatarColorFromText(dbUser.email),
      },
    });
  } catch (e) {
    console.error('Erro refresh token:', e);
    return res.status(500).json({ ok: false, error: 'Erro interno' });
  }
});

app.post('/api/email/enviar', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    if (!transporter) return res.status(500).json({ ok: false, error: 'smtp_not_configured' });
    const para = String(req.body?.para || req.body?.to || '').trim();
    const assunto = String(req.body?.assunto || req.body?.subject || '').trim();
    const corpo = String(req.body?.corpo || req.body?.html || '').trim();
    const anexosRaw = Array.isArray(req.body?.anexos) ? req.body.anexos : [];
    if (!para || !para.includes('@')) return res.status(400).json({ ok: false, error: 'para_invalido' });
    if (!assunto) return res.status(400).json({ ok: false, error: 'assunto_obrigatorio' });
    if (!corpo) return res.status(400).json({ ok: false, error: 'corpo_obrigatorio' });

    const attachments = [];
    for (const a of anexosRaw.slice(0, 10)) {
      if (!a || typeof a !== 'object') continue;
      const filename = String(a.nome || a.filename || 'anexo').trim() || 'anexo';
      const contentType = String(a.tipo || a.contentType || 'application/octet-stream').trim() || 'application/octet-stream';
      let base64 = String(a.base64 || a.content || '').trim();
      if (!base64) continue;
      const comma = base64.indexOf(',');
      if (comma >= 0 && base64.slice(0, comma).toLowerCase().includes('base64')) base64 = base64.slice(comma + 1);
      base64 = base64.replace(/\s+/g, '');
      if (!base64) continue;
      attachments.push({ filename, content: base64, encoding: 'base64', contentType });
    }

    await transporter.sendMail({
      from: `"Italy Embalagens" <${String(process.env.EMAIL_USER || '').trim()}>`,
      to: para,
      subject: assunto,
      html: corpo,
      attachments,
    });
    return res.json({ ok: true, msg: 'Email enviado com sucesso' });
  } catch (e) {
    console.error('[EMAIL ERROR]', String(e?.message || e));
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

