app.get('/api/usuarios/lista', authMiddleware, async (req, res) => {
  try {
    const isMissingColumnErr = (err) => {
      const msg = String(err?.message || err || '').toLowerCase();
      return msg.includes('could not find the') || msg.includes('does not exist');
    };
    const extractMissingCol = (err) => {
      const msg = String(err?.message || err || '');
      const m1 = msg.match(/Could not find the '([^']+)' column/i);
      const m2 = msg.match(/column\s+"?(\w+)"?\s+does not exist/i);
      return (m1 && m1[1]) || (m2 && m2[1]) || null;
    };

    let r = await supabase
      .from('usuarios')
      .select('id,nome,email,perfil,avatar_url,ativo,avatar_iniciais,avatar_cor')
      .order('nome', { ascending: true });

    if (r?.error && isMissingColumnErr(r.error) && extractMissingCol(r.error) === 'ativo') {
      r = await supabase
        .from('usuarios')
        .select('id,nome,email,perfil,avatar_url,avatar_iniciais,avatar_cor')
        .order('nome', { ascending: true });
    }

    if (r?.error) {
      console.error('[usuarios/lista]', String(r.error?.message || r.error));
      throw r.error;
    }

    const lista = (r?.data || []).filter((u) => u && u.ativo !== false);
    console.log('[usuarios/lista] retornando:', lista.length, 'usuarios');
    res.json({ ok: true, data: lista, usuarios: lista });
  } catch (e) {
    res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.get('/api/comissoes/relatorio', autenticar, async (req, res) => { 
  try { 
    const { mes, ano } = req.query; 
    if (!mes || !ano) return res.json({ ok: false, error: 'mes e ano obrigatorios' }); 

    const mesStr = String(mes).padStart(2, '0'); 
    const inicio = `${ano}-${mesStr}-01`; 
    const fimAno = parseInt(mes) === 12 ? parseInt(ano)+1 : parseInt(ano); 
    const fimMes = parseInt(mes) === 12 ? '01' : String(parseInt(mes)+1).padStart(2,'0'); 
    const fim = `${fimAno}-${fimMes}-01`; 

    console.log('[COM] buscando', inicio, 'ate', fim); 

    const { data: ofs, error } = await supabase 
      .from('vw_comissoes') 
      .select('*') 
      .gte('data_conclusao', inicio) 
      .lt('data_conclusao', fim) 
      .ilike('status', '%conclu%'); 

    if (error) { 
      console.error('[COM] erro view:', error.message); 
      return res.json({ ok: false, error: error.message }); 
    } 

    console.log('[COM] OFs da view:', ofs?.length); 

    let todasOFs = Array.isArray(ofs) ? ofs.slice() : []; 
    try {
      const missingQtdIds = todasOFs
        .filter(of => of && of.id && (of.quantidade == null && of.qtd == null && of.qtd_pedida == null))
        .map(of => String(of.id).trim())
        .filter(Boolean);
      if (missingQtdIds.length) {
        const mapaQtd = {};
        const chunkSize = 100;
        for (let i = 0; i < missingQtdIds.length; i += chunkSize) {
          const chunk = missingQtdIds.slice(i, i + chunkSize);
          const { data: ofsQtd, error: errQtd } = await supabase
            .from('ofs')
            .select('id,quantidade,qtd,qtd_pedida')
            .in('id', chunk);
          if (errQtd) continue;
          (ofsQtd || []).forEach(row => {
            mapaQtd[String(row.id)] = row;
          });
        }
        todasOFs.forEach(of => {
          const row = mapaQtd[String(of && of.id || '')];
          if (!row) return;
          if (of.quantidade == null && row.quantidade != null) of.quantidade = row.quantidade;
          if (of.qtd == null && row.qtd != null) of.qtd = row.qtd;
          if (of.qtd_pedida == null && row.qtd_pedida != null) of.qtd_pedida = row.qtd_pedida;
        });
      }
    } catch (_) {}
    try {
      const idsValor = todasOFs
        .map(of => String(of && of.id || '').trim())
        .filter(Boolean);
      if (idsValor.length) {
        const mapaValor = {};
        const chunkSizeValor = 100;
        for (let i = 0; i < idsValor.length; i += chunkSizeValor) {
          const chunk = idsValor.slice(i, i + chunkSizeValor);
          const { data: ofsValor, error: errValor } = await supabase
            .from('ofs')
            .select('id,valor_total,valor_venda,preco,total')
            .in('id', chunk);
          if (errValor) continue;
          (ofsValor || []).forEach(row => {
            mapaValor[String(row.id)] = row;
          });
        }
        todasOFs.forEach(of => {
          const row = mapaValor[String(of && of.id || '')];
          if (!row) return;
          if (row.valor_total != null) of.valor_total = row.valor_total;
          if (row.valor_venda != null) of.valor_venda = row.valor_venda;
          if (row.preco != null) of.preco = row.preco;
        });
      }
    } catch (_) {}
    try {
      todasOFs = await _enriquecerRespostaOFs(todasOFs);
    } catch (_) {}

    // Agrupar por vendedor 
    const porVend = {}; 
    let totalGeral = 0; 
    todasOFs.forEach(of => { 
      const val = Number(of.valor_total ?? of.total ?? of.valor_venda ?? 0) || 0; 
      if (!val) return; 
      totalGeral += val; 
      const vid = of.vendedor_id || of.vendId || of.vend_id || of.vendid || '__sem__'; 
      const nome = of.vendedor_nome || of.vendedor || of.vendNome || 'Sem Vendedor'; 
      const pct = Number(of.comissao_pct || 1); 
      if (!porVend[vid]) { 
        porVend[vid] = { id: vid, nome, comissao_pct: pct, ofs: 0, total: 0 }; 
      } 
      porVend[vid].ofs++; 
      porVend[vid].total += val; 
    }); 

    const vendedoresResult = Object.values(porVend) 
      .sort((a,b) => b.total - a.total) 
      .map(v => ({ ...v, comissao_rs: v.total * (v.comissao_pct/100) })); 

    const ofsDetalhadas = todasOFs.map(of => { 
      const valor_total = Number(of.valor_total ?? of.total ?? of.valor_venda ?? 0) || 0; 
      const comissao_pct = Number(of.comissao_pct || 1); 
      const comissao_rs = (of.comissao_rs != null) ? Number(of.comissao_rs || 0) : (valor_total * (comissao_pct/100)); 
      return { 
        id: of.id, 
        numero: of.numero || of.of, 
        cli_id: of.cli_id || of.cliId || of.cliente_id || of.clienteId || null, 
        vendedor_id: of.vendedor_id || of.vendId || of.vend_id || null, 
        cliente: of.clinome || of.cliente_nome || of.cliNome || of.cliente || '—', 
        vendedor: of.vendedor || of.vendedor_nome || of.vendNome || 'Sem Vendedor', 
        quantidade: of.quantidade ?? of.qtd ?? of.qtd_pedida ?? null, 
        valor_total, 
        total: valor_total,
        comissao_pct, 
        comissao_rs, 
        created_at: of.created_at || null, 
        data_conclusao: of.data_conclusao, 
        status: of.status || '—' 
      }; 
    }); 

    const totalComissao = vendedoresResult.reduce((s,v) => s+v.comissao_rs, 0); 
    console.log('[COM] FINAL ofs:', todasOFs.length, 'total:', totalGeral); 

    return res.json({ 
      ok: true, 
      mes: `${ano}-${mesStr}`, 
      total_ofs: todasOFs.length, 
      total_vendido: totalGeral, 
      total_comissao: totalComissao, 
      vendedores: vendedoresResult, 
      ofs: ofsDetalhadas 
    }); 
  } catch(e) { 
    console.error('[COM] erro:', e.message); 
    return res.json({ ok: false, error: e.message }); 
  } 
}); 

app.get('/api/backup/exportar', authMiddleware, async (req, res) => {
  try {
    if (!supabase) return res.status(500).json({ ok: false, error: 'supabase_not_configured' });
    const PAGE = 1000;

    let ofs = [];
    for (let from = 0; ; from += PAGE) {
      const { data, error } = await supabase
        .from('ofs')
        .select('*')
        .is('deleted_at', null)
        .range(from, from + PAGE - 1);
      if (error) throw error;
      if (!(data && data.length)) break;
      ofs = ofs.concat(data);
      if (data.length < PAGE) break;
    }

    let clientes = [];
    for (let from2 = 0; ; from2 += PAGE) {
      const { data, error } = await supabase
        .from('clientes')
        .select('*')
        .range(from2, from2 + PAGE - 1);
      if (error) throw error;
      if (!(data && data.length)) break;
      clientes = clientes.concat(data);
      if (data.length < PAGE) break;
    }

    const backup = {
      exportado_em: new Date().toISOString(),
      versao: '1.0',
      total_ofs: ofs.length,
      total_clientes: clientes.length,
      ofs,
      clientes,
    };

    res.setHeader('Content-Type', 'application/json');
    res.setHeader(
      'Content-Disposition',
      `attachment; filename="backup-italy-${new Date().toISOString().slice(0, 10)}.json"`
    );
    return res.json(backup);
  } catch (e) {
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.post('/api/backup/importar', authMiddleware, async (req, res) => {
  try {
    if (!supabase) return res.status(500).json({ ok: false, error: 'supabase_not_configured' });
    const ofs = Array.isArray(req.body?.ofs) ? req.body.ofs : [];
    const clientes = Array.isArray(req.body?.clientes) ? req.body.clientes : [];
    let ofs_ok = 0;
    let cli_ok = 0;
    const erros = [];

    for (let i = 0; i < clientes.length; i += 100) {
      const lote = clientes.slice(i, i + 100);
      const { error } = await supabase.from('clientes').upsert(lote, { onConflict: 'id' });
      if (error) erros.push('clientes lote ' + i + ': ' + error.message);
      else cli_ok += lote.length;
    }

    for (let i = 0; i < ofs.length; i += 100) {
      const lote = ofs.slice(i, i + 100);
      const { error } = await supabase.from('ofs').upsert(lote, { onConflict: 'id' });
      if (error) erros.push('ofs lote ' + i + ': ' + error.message);
      else ofs_ok += lote.length;
    }

    return res.json({
      ok: true,
      ofs_importadas: ofs_ok,
      clientes_importados: cli_ok,
      erros,
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.get('/api/ofs/vendedores-unicos', authMiddleware, async (req, res) => {
  try {
    if (!supabase) return res.status(500).json({ ok: false, error: 'supabase_not_configured' });
    const empresaUuid = await _resolveEmpresaUuid(req).catch(() => null);
    const empLegacy = String(
      req.usuario?.emp_id ??
      req.usuario?.empId ??
      req.user?.emp_id ??
      req.user?.empId ??
      ''
    ).trim();
    const empresaCandidates = [
      empresaUuid ? { col: 'empresa_id', val: empresaUuid } : null,
      empLegacy ? { col: 'emp_id', val: empLegacy } : null,
      empLegacy ? { col: 'empId', val: empLegacy } : null,
    ].filter((x, i, arr) => x && arr.findIndex((y) => y.col === x.col && String(y.val) === String(x.val)) === i);

    const isMissingColumnErr = (error) => {
      const msg = String(error?.message || error || '').toLowerCase();
      return msg.includes('column') || msg.includes('could not find');
    };

    const trySelects = [
      'vendedor,representante,status,created_at',
      'vendedor_nome,vendNome,status,created_at',
      '*',
    ];

    let rows = [];
    let lastError = null;
    for (const sel of trySelects) {
      for (const cand of (empresaCandidates.length ? empresaCandidates : [null])) {
        try {
          let q = supabase.from('ofs').select(sel).order('created_at', { ascending: false }).limit(20000);
          if (cand?.col && cand?.val) q = q.eq(cand.col, cand.val);
          const { data, error } = await q;
          if (!error) { rows = Array.isArray(data) ? data : []; lastError = null; break; }
          if (isMissingColumnErr(error)) { lastError = error; continue; }
          throw error;
        } catch (e) {
          if (isMissingColumnErr(e)) { lastError = e; continue; }
          throw e;
        }
      }
      if (rows.length) break;
    }
    if (!rows.length && lastError) throw lastError;

    const set = new Set();
    const norm = (v) => String(v || '').trim();
    rows.forEach((o) => {
      const st = String(o?.status || '').toLowerCase();
      if (st.includes('cancel')) return;
      const a = norm(o?.vendedor || o?.vendedor_nome || o?.vendNome);
      const b = norm(o?.representante);
      if (a) set.add(a);
      if (b) set.add(b);
    });
    return res.json({ ok: true, data: Array.from(set).sort((a, b) => a.localeCompare(b)) });
  } catch (e) {
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.post('/api/usuarios', requireAdmin, async (req, res) => {
  try {
    const nome = String(req.body?.nome || '').trim();
    const email = String(req.body?.email || '').trim().toLowerCase();
    const senha = String(req.body?.senha || '').trim();
    const perfil = String(req.body?.perfil || 'custom').trim();
    const ativo = req.body?.ativo !== undefined ? !!req.body.ativo : true;
    const avatar_cor = String(req.body?.avatar_cor || '').trim();
    let permissoes = req.body?.permissoes;
    if (typeof permissoes === 'string') { try { permissoes = JSON.parse(permissoes); } catch (_) { permissoes = []; } }
    if (!Array.isArray(permissoes)) permissoes = [];
    const canais_chat = Array.isArray(req.body?.canais_chat) ? req.body.canais_chat : undefined;

    if (!nome || !email || !senha) return res.status(400).json({ ok: false, error: 'nome, email e senha são obrigatórios' });
    const senha_hash = await bcrypt.hash(senha, 10);

    const row = {
      nome,
      email,
      senha_hash,
      perfil: perfil === 'admin' ? 'admin' : 'custom',
      permissoes: perfil === 'admin' ? ['tudo'] : permissoes,
      canais_chat: canais_chat !== undefined ? canais_chat : undefined,
      ativo,
      avatar_iniciais: String(req.body?.avatar_iniciais || '').trim() || initialsFromName(nome),
      avatar_cor: avatar_cor || avatarColorFromText(email),
    };

    const { data, error } = await supabase.from('usuarios').insert([row]).select('id,nome,email,perfil,permissoes,canais_chat,ativo,avatar_iniciais,avatar_cor,criado_em,ultimo_acesso').single();
    if (error) throw error;
    await logAuditoria('usuarios', 'INSERT', data?.id, null, data, req);
    return ok(res, data);
  } catch (e) { return err(res, e); }
});

app.put('/api/usuarios/:id', requireAdmin, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    if (!id) return res.status(400).json({ ok: false, error: 'id obrigatório' });

    let antes = null;
    try {
      const r0 = await supabase.from('usuarios').select('*').eq('id', id).maybeSingle();
      antes = r0?.data || null;
    } catch (_) {}

    const payload = { ...req.body };
    delete payload.id;
    delete payload.senha;
    delete payload.senha_hash;

    if (payload.email != null) payload.email = String(payload.email || '').trim().toLowerCase();
    if (payload.nome != null) payload.nome = String(payload.nome || '').trim();
    if (payload.perfil === 'admin') payload.permissoes = ['tudo'];
    if (payload.perfil && payload.perfil !== 'admin') payload.perfil = 'custom';
    if (payload.ativo != null) payload.ativo = !!payload.ativo;
    if (payload.permissoes != null && !Array.isArray(payload.permissoes)) payload.permissoes = [];
    if (payload.canais_chat != null && !Array.isArray(payload.canais_chat)) payload.canais_chat = [];

    const { data, error } = await supabase
      .from('usuarios')
      .update(payload)
      .eq('id', id)
      .select('id,nome,email,perfil,permissoes,canais_chat,ativo,avatar_iniciais,avatar_cor,criado_em,ultimo_acesso')
      .single();
    if (error) throw error;
    await logAuditoria('usuarios', 'UPDATE', id, antes, data, req);
    return ok(res, data);
  } catch (e) { return err(res, e); }
});

