app.post('/api/usuarios/corrigir_login', requireAdmin, async (req, res) => {
  try {
    const dryRun = String(req.body?.dry_run || req.query?.dry_run || '').trim() === '1';
    const isMissingColumnErr = (err) => {
      const msg = String(err?.message || err || '').toLowerCase();
      return msg.includes('could not find the') || msg.includes('does not exist');
    };
    const extractMissingCol = (err) => {
      const msg = String(err?.message || err || '');
      const m1 = msg.match(/Could not find the '([^']+)' column/i);
      const m2 = msg.match(/column\s+"([^"]+)"\s+does not exist/i);
      return (m1 && m1[1]) || (m2 && m2[1]) || null;
    };
    const updateDroppingUnknown = async (id, patch) => {
      let cur = { ...(patch || {}) };
      let lastErr = null;
      for (let tentativa = 0; tentativa < 10; tentativa++) {
        const { error: e2 } = await supabase.from('usuarios').update(cur).eq('id', id);
        if (!e2) return { ok: true, patch: cur };
        lastErr = e2;
        if (!isMissingColumnErr(e2)) throw e2;
        const col = extractMissingCol(e2);
        if (col && Object.prototype.hasOwnProperty.call(cur, col)) { delete cur[col]; continue; }
        throw e2;
      }
      if (lastErr) throw lastErr;
      return { ok: false };
    };

    let rows = null;
    let error = null;
    try {
      const r = await supabase
        .from('usuarios')
        .select('id,email,perfil,ativo,permissoes,senha_hash,senha')
        .limit(5000);
      rows = r.data;
      error = r.error;
    } catch (e1) {
      error = e1;
    }
    if (error) throw error;
    const list = Array.isArray(rows) ? rows : [];
    const updates = [];
    const affected = [];
    list.forEach((u) => {
      const id = String(u?.id || '').trim();
      if (!id) return;
      const perfilNorm = String(u?.perfil || '').trim().toLowerCase();
      const isAdmin = perfilNorm === 'admin' || perfilNorm.includes('admin');

      const patch = {};

      if (u?.ativo === null || u?.ativo === undefined) patch.ativo = true;

      let perms = u?.permissoes;
      if (typeof perms === 'string') {
        try { perms = JSON.parse(perms); } catch (_) { perms = []; }
      }
      if (!Array.isArray(perms)) perms = [];
      if (isAdmin && !perms.includes('tudo')) perms = ['tudo', ...perms];
      if (u?.permissoes == null || (typeof u?.permissoes === 'string') || !Array.isArray(u?.permissoes)) patch.permissoes = perms;

      const senhaHash = String(u?.senha_hash || '').trim();
      const senhaAlt = String(u?.senha || '').trim();
      const hashLooksBcrypt = (h) => typeof h === 'string' && h.trim().startsWith('$2');
      const hashIsOk = hashLooksBcrypt(senhaHash);

      if (!hashIsOk) {
        if (hashLooksBcrypt(senhaAlt)) {
          patch.senha_hash = senhaAlt;
          patch.senha = null;
          patch.precisa_trocar_senha = true;
          patch.trocar_senha = true;
        } else if (senhaAlt) {
          try {
            patch.senha_hash = bcrypt.hashSync(senhaAlt, 10);
            patch.senha = null;
            patch.precisa_trocar_senha = true;
            patch.trocar_senha = true;
          } catch (_) {}
        } else {
          const tmp = 'Tmp@' + crypto.randomBytes(6).toString('hex');
          try {
            patch.senha_hash = bcrypt.hashSync(tmp, 10);
            patch.precisa_trocar_senha = true;
            patch.trocar_senha = true;
            patch._senha_tmp = tmp;
          } catch (_) {}
        }
      }

      if (Object.keys(patch).length) {
        updates.push({ id, patch });
        const { _senha_tmp, ...patchOut } = patch;
        affected.push({ id, email: u?.email || null, patch: patchOut, ...(patch._senha_tmp ? { senha_tmp: patch._senha_tmp } : {}) });
      }
    });

    if (dryRun) {
      return res.json({ ok: true, dry_run: true, total: updates.length, affected: affected.slice(0, 50) });
    }

    let okCount = 0;
    for (const u of updates) {
      const { _senha_tmp, ...patch } = u.patch || {};
      await updateDroppingUnknown(u.id, patch);
      okCount++;
    }
    return res.json({ ok: true, updated: okCount, total: updates.length, affected: affected.slice(0, 50) });
  } catch (e) {
    return err(res, e);
  }
});

app.delete('/api/usuarios/:id', requireAdmin, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    if (!id) return res.status(400).json({ ok: false, error: 'id obrigatório' });

    if (String(req.usuario?.id || '') === id) {
      return res.status(400).json({ error: 'Você não pode deletar seu próprio usuário' });
    }

    const ADMINS_PROTEGIDOS = ['sidao', 'mano', 'italy'];
    const { data: uDel, error: uDelErr } = await supabase
      .from('usuarios')
      .select('email,perfil')
      .eq('id', id)
      .maybeSingle();
    if (uDelErr) throw uDelErr;
    if (uDel && ADMINS_PROTEGIDOS.includes(String(uDel.email || '').toLowerCase())) {
      return res.status(403).json({ ok: false, error: 'Este usuário não pode ser excluído' });
    }

    const { data: admins, error: aerr } = await supabase
      .from('usuarios')
      .select('id')
      .eq('perfil', 'admin')
      .eq('ativo', true);
    if (aerr) throw aerr;
    if (Array.isArray(admins) && admins.length <= 1 && String(admins[0]?.id || '') === id) {
      return res.status(400).json({ error: 'Não é possível remover o único administrador do sistema' });
    }

    const { error } = await supabase.from('usuarios').delete().eq('id', id);
    if (error) throw error;
    return ok(res, true);
  } catch (e) { return err(res, e); }
});

app.post('/api/admin/limpar_uploads', requireAdmin, async (req, res) => {
  try {
    const dirs = [
      path.join(__dirname, 'uploads', 'of'),
      path.join(__dirname, 'uploads', 'chat')
    ];
    let total = 0;
    for (const dir of dirs) {
      if (!fs.existsSync(dir)) continue;
      const files = fs.readdirSync(dir);
      for (const f of files) {
        const p = path.join(dir, f);
        try {
          const st = fs.statSync(p);
          if (st.isFile()) {
            fs.unlinkSync(p);
            total++;
          }
        } catch (e) {}
      }
    }
    return ok(res, { deletados: total });
  } catch (e) { return err(res, e); }
});

