async function _buscarClienteNomeOF(cliId) {
  const id = String(cliId || '').trim();
  if (!id) return '';
  try {
    const { data } = await supabase
      .from('clientes')
      .select('nome,rs,razao_social')
      .eq('id', id)
      .maybeSingle();
    return String(data?.nome || data?.rs || data?.razao_social || '').trim();
  } catch (_) {
    return '';
  }
}

async function _buscarVendedorNomeOF(vendedorId) {
  const id = String(vendedorId || '').trim();
  if (!id) return '';
  try {
    const { data } = await supabase
      .from('vendedores')
      .select('nome')
      .eq('id', id)
      .maybeSingle();
    return String(data?.nome || '').trim();
  } catch (_) {
    return '';
  }
}

async function _preencherCamposCriticosOF(input, opts = {}) {
  const out = { ...(input || {}) };
  const onlyClinome = !!opts.onlyClinome;
  const parseItens = (v) => {
    if (Array.isArray(v)) return v;
    if (typeof v === 'string') {
      try {
        const parsed = JSON.parse(v || '[]');
        return Array.isArray(parsed) ? parsed : [];
      } catch (_) {
        return [];
      }
    }
    return [];
  };
  const toNum = (v) => {
    if (v === undefined || v === null || v === '') return 0;
    const n = Number(String(v).replace(',', '.'));
    return Number.isFinite(n) ? n : 0;
  };

  const cliId = String(out.cli_id ?? out.cliId ?? out.cliente_id ?? out.cliid ?? '').trim();
  let clinome = String(out.clinome ?? out.cliNome ?? out.cliente_nome ?? out.cliente ?? '').trim();
  if (!clinome && cliId) clinome = await _buscarClienteNomeOF(cliId);
  if (clinome) {
    out.clinome = clinome;
    if (out.cliNome === undefined || out.cliNome === '') out.cliNome = clinome;
    if (out.cliente_nome === undefined || out.cliente_nome === '') out.cliente_nome = clinome;
  }
  if (onlyClinome) return out;

  const vendedorId = String(out.vendedor_id ?? out.vendId ?? out.vend_id ?? '').trim();
  let vendedor = String(out.vendedor ?? out.vendNome ?? out.vendedor_nome ?? '').trim();
  if (!vendedor && vendedorId) vendedor = await _buscarVendedorNomeOF(vendedorId);
  let vendid = String(out.vendid ?? '').trim();
  if (!vendid) vendid = String(out.vendId ?? out.vend_id ?? out.vendedor_id ?? '').trim();
  if (!vendid) vendid = vendedor;
  if (!vendedor && vendid) vendedor = vendid;
  if (vendedor) {
    out.vendedor = vendedor;
    if (out.vendNome === undefined || out.vendNome === '') out.vendNome = vendedor;
    if (out.vendedor_nome === undefined || out.vendedor_nome === '') out.vendedor_nome = vendedor;
  }
  if (vendid) out.vendid = vendid;

  const itens = parseItens(out.itens);
  const qtd = Math.trunc(toNum(out.qtd ?? out.quantidade ?? out.qtd_pedida));
  const itemPreco = Math.max(0, ...itens.map((it) => toNum(it?.valor_unitario ?? it?.vunit ?? it?.preco)));
  const itemTotal = itens.reduce((sum, it) => sum + toNum(it?.valor_total ?? it?.total), 0);
  const preco = toNum(out.preco ?? out.valor_unitario ?? out.vl_unit ?? out.vunit) || itemPreco;
  let total = toNum(out.total ?? out.valor_total ?? out.valor_venda);
  if (!(total > 0) && itemTotal > 0) total = itemTotal;
  if (!(total > 0) && qtd > 0 && preco > 0) total = Math.round((preco * qtd) * 100) / 100;

  if (qtd > 0) {
    out.qtd = qtd;
    if (out.quantidade === undefined || !(Number(out.quantidade) > 0)) out.quantidade = qtd;
    if (out.qtd_pedida === undefined || !(Number(out.qtd_pedida) > 0)) out.qtd_pedida = qtd;
  }
  if (preco > 0) {
    out.preco = preco;
    if (out.valor_unitario === undefined || !(toNum(out.valor_unitario) > 0)) out.valor_unitario = preco;
    if (out.vl_unit === undefined || !(toNum(out.vl_unit) > 0)) out.vl_unit = preco;
  }
  if (total > 0) {
    out.total = total;
    if (out.valor_total === undefined || !(toNum(out.valor_total) > 0)) out.valor_total = total;
    if (out.valor_venda === undefined || !(toNum(out.valor_venda) > 0)) out.valor_venda = total;
  }

  return out;
}

async function _enriquecerRespostaOFs(listaInput) {
  const lista = (Array.isArray(listaInput) ? listaInput : [])
    .filter((item) => item && typeof item === 'object')
    .map((item) => ({ ...item }));
  if (!lista.length) return [];

  const parseItens = (v) => {
    if (Array.isArray(v)) return v;
    if (typeof v === 'string') {
      try {
        const parsed = JSON.parse(v || '[]');
        return Array.isArray(parsed) ? parsed : [];
      } catch (_) {
        return [];
      }
    }
    return [];
  };
  const toNum = (v) => {
    if (v === undefined || v === null || v === '') return 0;
    const n = Number(String(v).replace(',', '.'));
    return Number.isFinite(n) ? n : 0;
  };
  const pickText = (...values) => {
    for (const value of values) {
      const text = String(value == null ? '' : value).trim();
      if (text) return text;
    }
    return '';
  };
  const isUuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v).trim());

  const ids = Array.from(new Set(lista.map((item) => String(item?.id || '').trim()).filter(Boolean)));
  const baseMap = new Map();
  const chunkSize = 200;
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    if (!chunk.length) continue;
    try {
      const { data, error } = await supabase
        .from('ofs')
        .select('id,of,numero,cli_id,cliId,cliente_id,clinome,cliNome,cliente_nome,cliente,vendedor,vendid,vendId,vend_id,vendedor_id,vendedor_nome,vendNome,preco,valor_unitario,vl_unit,total,valor_total,valor_venda,qtd,quantidade,qtd_pedida,itens')
        .in('id', chunk);
      if (error) continue;
      (Array.isArray(data) ? data : []).forEach((row) => {
        const rowId = String(row?.id || '').trim();
        if (rowId) baseMap.set(rowId, row);
      });
    } catch (_) {}
  }

  const cliIds = Array.from(new Set(lista.map((item) => {
    const base = baseMap.get(String(item?.id || '').trim()) || {};
    return pickText(item?.cli_id, item?.cliId, item?.cliente_id, base?.cli_id, base?.cliId, base?.cliente_id);
  }).filter(Boolean)));
  const clienteMap = new Map();
  for (let i = 0; i < cliIds.length; i += chunkSize) {
    const chunk = cliIds.slice(i, i + chunkSize);
    if (!chunk.length) continue;
    try {
      const { data, error } = await supabase
        .from('clientes')
        .select('id,nome,rs,vendedor_id')
        .in('id', chunk);
      if (error) continue;
      (Array.isArray(data) ? data : []).forEach((cli) => {
        const cliId = String(cli?.id || '').trim();
        if (cliId) clienteMap.set(cliId, cli);
      });
    } catch (_) {}
  }

  const vendedorIds = Array.from(new Set(lista.map((item) => {
    const base = baseMap.get(String(item?.id || '').trim()) || {};
    const cliId = pickText(item?.cli_id, item?.cliId, item?.cliente_id, base?.cli_id, base?.cliId, base?.cliente_id);
    const cli = clienteMap.get(cliId) || {};
    return pickText(item?.vendedor_id, item?.vendId, item?.vend_id, base?.vendedor_id, base?.vendId, base?.vend_id, cli?.vendedor_id);
  }).filter(Boolean).filter((id) => isUuid(id))));
  const vendedorMap = new Map();
  for (let i = 0; i < vendedorIds.length; i += chunkSize) {
    const chunk = vendedorIds.slice(i, i + chunkSize);
    if (!chunk.length) continue;
    try {
      const { data, error } = await supabase
        .from('vendedores')
        .select('id,nome')
        .in('id', chunk);
      if (error) continue;
      (Array.isArray(data) ? data : []).forEach((vend) => {
        const vendId = String(vend?.id || '').trim();
        if (vendId) vendedorMap.set(vendId, String(vend?.nome || '').trim());
      });
    } catch (_) {}
  }

  return lista.map((item) => {
    const rowId = String(item?.id || '').trim();
    const base = baseMap.get(rowId) || {};
    const cliId = pickText(item?.cli_id, item?.cliId, item?.cliente_id, base?.cli_id, base?.cliId, base?.cliente_id);
    const cliente = clienteMap.get(cliId) || {};
    const vendedorId = pickText(item?.vendedor_id, item?.vendId, item?.vend_id, base?.vendedor_id, base?.vendId, base?.vend_id, cliente?.vendedor_id);
    const vendedorNome = pickText(
      item?.vendedor,
      item?.vendedor_nome,
      item?.vendNome,
      isUuid(String(item?.vendid || '').trim()) ? '' : item?.vendid,
      base?.vendedor,
      base?.vendedor_nome,
      base?.vendNome,
      isUuid(String(base?.vendid || '').trim()) ? '' : base?.vendid,
      vendedorMap.get(String(vendedorId || '').trim())
    );
    const vendid = pickText(
      !isUuid(String(item?.vendid || '').trim()) ? item?.vendid : '',
      !isUuid(String(base?.vendid || '').trim()) ? base?.vendid : '',
      vendedorNome,
      vendedorId
    );
    const clinome = pickText(
      item?.clinome,
      item?.cliNome,
      item?.cliente_nome,
      item?.cliente,
      base?.clinome,
      base?.cliNome,
      base?.cliente_nome,
      base?.cliente,
      cliente?.nome,
      cliente?.rs
    );
    const itens = parseItens(item?.itens ?? base?.itens);
    const qtd = Math.trunc(toNum(item?.qtd ?? item?.quantidade ?? item?.qtd_pedida ?? base?.qtd ?? base?.quantidade ?? base?.qtd_pedida ?? itens?.[0]?.qtd ?? itens?.[0]?.quantidade));
    let preco = toNum(item?.preco ?? item?.valor_unitario ?? item?.vl_unit ?? base?.preco ?? base?.valor_unitario ?? base?.vl_unit ?? itens?.[0]?.valor_unitario ?? itens?.[0]?.vunit ?? itens?.[0]?.preco);
    let total = toNum(item?.total ?? item?.valor_total ?? item?.valor_venda ?? base?.total ?? base?.valor_total ?? base?.valor_venda ?? itens?.[0]?.valor_total ?? itens?.[0]?.total);
    if (!(preco > 0) && qtd > 0 && total > 0) preco = Math.round((total / qtd) * 100) / 100;
    if (!(total > 0) && preco > 0 && qtd > 0) total = Math.round((preco * qtd) * 100) / 100;

    return {
      ...base,
      ...item,
      id: rowId || base?.id || item?.id || null,
      cli_id: cliId || null,
      cliId: cliId || null,
      cliente_id: cliId || null,
      clinome: clinome || '—',
      cliNome: clinome || '—',
      cliente_nome: clinome || '—',
      cliente: clinome || '—',
      vendedor_id: vendedorId || null,
      vendId: vendedorId || null,
      vend_id: vendedorId || null,
      vendedor: vendedorNome || '—',
      vendedor_nome: vendedorNome || '—',
      vendNome: vendedorNome || '—',
      vendid: vendid || '—',
      preco: preco > 0 ? preco : 0,
      valor_unitario: preco > 0 ? preco : toNum(item?.valor_unitario ?? base?.valor_unitario ?? item?.vl_unit ?? base?.vl_unit),
      vl_unit: preco > 0 ? preco : toNum(item?.vl_unit ?? base?.vl_unit ?? item?.valor_unitario ?? base?.valor_unitario),
      total: total > 0 ? total : 0,
      valor_total: total > 0 ? total : toNum(item?.valor_total ?? base?.valor_total ?? item?.valor_venda ?? base?.valor_venda),
      valor_venda: total > 0 ? total : toNum(item?.valor_venda ?? base?.valor_venda ?? item?.valor_total ?? base?.valor_total),
      qtd: qtd > 0 ? qtd : (item?.qtd ?? item?.quantidade ?? item?.qtd_pedida ?? base?.qtd ?? base?.quantidade ?? base?.qtd_pedida ?? null),
      quantidade: qtd > 0 ? qtd : (item?.quantidade ?? item?.qtd ?? base?.quantidade ?? base?.qtd ?? null),
      qtd_pedida: qtd > 0 ? qtd : (item?.qtd_pedida ?? base?.qtd_pedida ?? null),
      numero: pickText(item?.numero, item?.of, base?.numero, base?.of),
      of: pickText(item?.of, item?.numero, base?.of, base?.numero),
    };
  });
}

async function ofsInsertWithRetry(row) {
  function sanitizarPayloadOF(payload) {
    const inteiros = [
      'qtd', 'quantidade', 'qtd_pedida',
      'qtd_produzida', 'qtd_perdida', 'caixas_excedentes',
      'maquina_atual_index', 'prioridade', 'prioridade_producao'
    ];
    const decimais = [
      'valor_total', 'valor_venda', 'valor_unitario', 'preco',
      'caixa_comprimento', 'caixa_largura', 'caixa_altura'
    ];
    const out = { ...(payload || {}) };
    const toIntOr = (v) => {
      if (v === undefined || v === null) return null;
      const s = String(v).trim();
      if (!s) return null;
      const n = Math.round(Number(s.replace(',', '.')));
      return Number.isFinite(n) ? n : null;
    };
    const toDecOr = (v) => {
      if (v === undefined || v === null) return null;
      const s = String(v).trim();
      if (!s) return null;
      const n = parseFloat(s.replace(',', '.'));
      return Number.isFinite(n) ? n : null;
    };
    inteiros.forEach((k) => {
      if (out[k] === undefined) return;
      const n = toIntOr(out[k]);
      if (n === null) delete out[k];
      else out[k] = n;
    });
    decimais.forEach((k) => {
      if (out[k] === undefined) return;
      const n = toDecOr(out[k]);
      if (n === null) delete out[k];
      else out[k] = n;
    });
    if (Array.isArray(out.itens)) {
      out.itens = out.itens.map((item) => {
        if (!item || typeof item !== 'object') return item;
        const qtd = toIntOr(item.qtd ?? item.quantidade ?? 0);
        const quantidade = toIntOr(item.quantidade ?? item.qtd ?? 0);
        const vunit = toDecOr(item.vunit ?? item.valor_unitario ?? 0);
        const valor_unitario = toDecOr(item.valor_unitario ?? item.vunit ?? 0);
        const valor_total = toDecOr(item.valor_total ?? item.total ?? 0);
        return {
          ...item,
          ...(qtd === null ? {} : { qtd }),
          ...(quantidade === null ? {} : { quantidade }),
          ...(vunit === null ? {} : { vunit }),
          ...(valor_unitario === null ? {} : { valor_unitario }),
          ...(valor_total === null ? {} : { valor_total }),
        };
      }).filter(Boolean);
    }
    return out;
  }

  let p = sanitizarPayloadOF({ ...(row || {}) });
  const ignoredColumns = [];
  for (let tentativa = 0; tentativa < 5; tentativa++) {
    const r = await supabase.from('ofs').insert([p]).select('*').single();
    if (!r.error) return r;
    const msg = String(r.error.message || r.error);
    const m1 = msg.match(/Could not find the '([^']+)' column/i);
    const m2 = msg.match(/column\s+"([^"]+)"\s+does not exist/i);
    const col = (m1 && m1[1]) || (m2 && m2[1]) || null;
    if (col && Object.prototype.hasOwnProperty.call(p, col)) {
      try { ignoredColumns.push(col); } catch (_) {}
      try { console.warn('[OFS INSERT] ignorando coluna inexistente:', col); } catch (_) {}
      delete p[col];
      continue;
    }
    r.ignoredColumns = ignoredColumns;
    return r;
  }
  return { data: null, error: { message: 'Falha ao inserir OF após tentativas' }, ignoredColumns };
}

