async function buscarTodasOFsPaginadas(montarQuery) {
  let todas = [];
  let from = 0;
  const pageSize = 1000;
  let countExact = 0;
  while (true) {
    let query = montarQuery();
    const { data, error, count } = await query.range(from, from + pageSize - 1);
    if (error) throw error;
    const lote = Array.isArray(data) ? data : [];
    if (from === 0 && Number.isFinite(Number(count))) countExact = Number(count);
    if (!lote.length) break;
    todas = todas.concat(lote);
    if (lote.length < pageSize) break;
    from += pageSize;
  }
  return { data: todas, count: countExact || todas.length };
}

app.get('/api/ofs', authMiddleware, async (req, res) => {
  try {
    if (!supabase) {
      return res.status(503).json({ ok: false, data: [], total: 0, offset: 0, limit: 0, hasMore: false, error: 'Supabase não configurado.' });
    }

    const empId = await resolverEmpresaId(req);
    if (!empId) return res.json({ ok: true, data: [], total: 0, offset: 0, limit: 0, hasMore: false });

    const after = String(req.query.after || '').trim();
    const afterIso = (after && after !== 'undefined' && after !== 'null' && after !== '[object Object]') ? after : '';
    const limitRaw = String(req.query.limit || '').trim();
    const limit = Math.min(parseInt(limitRaw, 10) || 500, 1000);
    const offset = parseInt(String(req.query.offset || ''), 10) || 0;
    const status = req.query.status;
    const busca = String(req.query.busca || req.query.search || '').trim();
    const clienteFiltro = String((req.query.cli_id || req.query.cliente_id || '') || '').trim();
    const empresaFiltro = req.query.empresa;
    const useCache = !afterIso;
    const cacheKey = useCache ? ('ofs_v12_' + empId + '_' + offset + '_' + limit + '_' + (status || '') + '_' + (busca || '') + '_' + (clienteFiltro || '')) : '';
    if (useCache) {
      const cached = cacheGet(cacheKey);
      if (cached) return res.json(cached);
    } else {
      setNoCache(res);
    }

    const buildQuery = () => {
      let query = supabase
        .from('ofs')
        .select('*', { count: 'exact' })
        .order('created_at', { ascending: false });

      if (empresaFiltro && empresaFiltro !== 'todas' && empresaFiltro !== 'all') {
        query = query.eq('empresa_id', empresaFiltro);
      } else {
        query = query.or('empresa_id.eq.' + empId + ',empresa_id.is.null');
      }

      if (status) {
        if (status.includes(',')) query = query.in('status', status.split(',').map((s) => String(s || '').trim()).filter(Boolean));
        else query = query.eq('status', status);
      }

      if (clienteFiltro && clienteFiltro !== 'undefined' && clienteFiltro !== 'null' && clienteFiltro !== '[object Object]') {
        query = query.eq('cli_id', clienteFiltro);
      }
      if (busca) {
        query = query.or('numero.ilike.%' + busca + '%,descricao.ilike.%' + busca + '%');
      }
      if (afterIso) {
        query = query.gte('created_at', afterIso);
      }
      return query;
    };

    const shouldFetchAll = !afterIso && !offset && (!limitRaw || limitRaw === 'all' || limitRaw === '0');
    let fetched = null;
    try {
      fetched = shouldFetchAll
        ? await buscarTodasOFsPaginadas(buildQuery)
        : await (async () => {
            const { data, error, count } = await buildQuery().range(offset, offset + limit - 1);
            if (error) throw error;
            return { data: data || [], count: count || 0 };
          })();
    } catch (queryErr) {
      try { console.error('[GET /api/ofs] erro query principal:', queryErr?.message || queryErr); } catch (_) {}
      try { console.error('[GET /api/ofs] stack query principal:', queryErr?.stack || ''); } catch (_) {}
      const fallbackQueryBase = () => {
        let query = supabase
          .from('ofs')
          .select('*', { count: 'exact' })
          .order('created_at', { ascending: false });
        if (empresaFiltro && empresaFiltro !== 'todas' && empresaFiltro !== 'all') query = query.eq('empresa_id', empresaFiltro);
        else query = query.or('empresa_id.eq.' + empId + ',empresa_id.is.null');
        if (afterIso) query = query.gte('created_at', afterIso);
        return query;
      };
      fetched = shouldFetchAll
        ? await buscarTodasOFsPaginadas(fallbackQueryBase)
        : await (async () => {
            const { data, error, count } = await fallbackQueryBase().range(offset, offset + limit - 1);
            if (error) throw error;
            return { data: data || [], count: count || 0 };
          })();
    }

    const data = fetched.data || [];
    const count = fetched.count || 0;

    const ofsRaw = data || [];
    const clienteIds = [...new Set(ofsRaw.map(o => o.cli_id).filter(Boolean))];
    const mapaClientes = {};
    if (clienteIds.length > 0) {
      try {
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        const idsValidos = clienteIds
          .map(id => String(id).trim())
          .filter(id => uuidRegex.test(id));

        console.debug('[CLIENTES] ids para resolver:', idsValidos.length);

        if (idsValidos.length > 0) {
          for (let i = 0; i < idsValidos.length; i += 50) {
            const lote = idsValidos.slice(i, i + 50);
            const { data: clientes, error: errCli } = await supabase
              .from('clientes')
              .select('id, nome, rs')
              .in('id', lote);

            if (errCli) {
              console.debug('[CLIENTES] erro .in():', errCli.message);
            }

            console.debug('[CLIENTES] lote', i, 'resultado:', clientes?.length);

            (clientes || []).forEach(c => {
              const nomeCliente = c.nome || c.rs || '';
              mapaClientes[c.id] = nomeCliente;
              mapaClientes[String(c.id).toLowerCase()] = nomeCliente;
              mapaClientes[String(c.id).toUpperCase()] = nomeCliente;
            });
          }
        }

        const idsCodigo = clienteIds
          .map(id => String(id).trim())
          .filter(id => !uuidRegex.test(id) && id.length > 0);

        if (idsCodigo.length > 0) {
          const { data: clientesCod } = await supabase
            .from('clientes')
            .select('id, nome, rs, codigo')
            .in('codigo', idsCodigo);
          (clientesCod || []).forEach(c => {
            const nome = c.nome || c.rs || '';
            if (c.codigo) mapaClientes[c.codigo] = nome;
            mapaClientes[c.id] = nome;
          });
        }

        console.debug('[CLIENTES] mapa size:', Object.keys(mapaClientes).length);
      } catch (e) {
        console.error('[CLIENTES] erro:', e.message);
      }
    }

    let rows = ofsRaw.map((of) => {
      const cliIdNorm = String(of.cli_id || '').trim();
      const clienteNome = of.clinome
        || mapaClientes[cliIdNorm]
        || mapaClientes[cliIdNorm.toLowerCase()]
        || mapaClientes[cliIdNorm.toUpperCase()]
        || '';
      let maquinaNome = '';
      try {
        let m = of?.maq;
        if (m) {
          if (typeof m === 'string') m = JSON.parse(m);
          if (Array.isArray(m)) {
            const nomes = m
              .map((x) => String(x || '').trim())
              .filter((x) => x && !/^[0-9a-f-]{36}$/i.test(x));
            maquinaNome = nomes.join(', ') || '';
          } else {
            const raw = String(m || '').trim();
            maquinaNome = /^[0-9a-f-]{36}$/i.test(raw) ? '' : raw;
          }
        }
      } catch (_) {}

      let itensArr = [];
      try {
        if (of?.itens) itensArr = typeof of.itens === 'string' ? JSON.parse(of.itens) : of.itens;
      } catch (_) {}
      if (!Array.isArray(itensArr)) itensArr = [];

      let produtoNome = of.descricao || '';
      let total = 0;
      try {
        if (of.itens) {
          itensArr = typeof of.itens === 'string' ? JSON.parse(of.itens) : of.itens;
          if (Array.isArray(itensArr) && itensArr[0]) {
            produtoNome = itensArr[0].descricao || itensArr[0].produto || of.descricao || '';
            total = itensArr.reduce((s, it) => s + Number(it.total || it.valor_total || 0), 0);
          }
        }
      } catch (e) {}

      let imgsArr = [];
      try {
        imgsArr = Array.isArray(of?.imgs) ? of.imgs : (typeof of?.imgs === 'string' ? JSON.parse(of.imgs) : []);
      } catch (_) {
        imgsArr = [];
      }
      imgsArr = Array.isArray(imgsArr) ? imgsArr.map((v) => String(v || '').trim()).filter(Boolean).filter(_urlValidaImagem) : [];
      const primeiraImagem = imgsArr[0] ? String(imgsArr[0] || '').trim() : '';
      const ofSafe = _sanitizeOfImagesForResponse(of);
      const iuRaw = String(ofSafe?.imagem_url || '').trim();
      const imagemUrl = _urlValidaImagem(iuRaw) ? iuRaw : (_urlValidaImagem(primeiraImagem) ? primeiraImagem : null);

      return {
        ...of,
        cliente: clienteNome,
        clinome: clienteNome,
        maquina: maquinaNome,
        maquina_atual: maquinaNome,
        produto: produtoNome,
        imagem_url: imagemUrl,
        imgs: ofSafe?.imgs ?? of?.imgs,
        total: total || of.total || 0,
        itens_parsed: itensArr,
        urgente: of.urgente || of.urg || false,
        numero: of.numero || of.of_num || of.of || ''
      };
    });

    if (busca) {
      const buscaNorm = String(busca).toLowerCase();
      rows = rows.filter((of) => {
        const hay = [
          of?.numero, of?.descricao, of?.produto, of?.cliente, of?.clinome, of?.cliente_nome
        ].map((v) => String(v || '').toLowerCase()).join(' ');
        return hay.includes(buscaNorm);
      });
    }

    const totalCount = count || rows.length;
    const hasMore = (offset + rows.length) < totalCount;
    const resultado = { ok: true, data: rows, total: totalCount, offset, limit, hasMore };
    if (useCache) cacheSet(cacheKey, resultado, 30000);
    return res.json(resultado);
  } catch (e) {
    try { console.error('[GET /api/ofs] erro:', e.message); } catch (_) {}
    try { console.error('[GET /api/ofs] stack:', e.stack); } catch (_) {}
    return res.status(500).json({ ok: false, error: e.message, ofs: [], data: [], total: 0, offset: 0, limit: 0, hasMore: false });
  }
});

// Rota dedicada para próximo número de OF
app.get('/api/ofs/proximo-numero', authMiddleware, async (req, res) => {
  try {
    const { data, error } = await supabase
      .from('ofs')
      .select('numero, of_num, of, id, created_at')
      .order('created_at', { ascending: false })
      .limit(200);

    if (error) throw error;

    let maior = 0;
    (data || []).forEach((of) => {
      ['numero', 'of_num', 'numero_of', 'of'].forEach((campo) => {
        const v = of?.[campo];
        if (v === null || v === undefined || v === '') return;
        const n = parseInt(String(v).replace(/\D/g, ''), 10);
        if (!isNaN(n) && n > maior) maior = n;
      });
    });

    const proximo = String(maior + 1).padStart(String(maior).length >= 3 ? String(maior).length : 3, '0');
    return res.json({ ok: true, proximo, maior });
  } catch (e) {
    return res.json({ ok: true, proximo: '001', maior: 0, erro: String(e?.message || e) });
  }
});

