async function _maybeRegistrarComissaoOF(req, body, ofRow) {
  try {
    const vendedorId = String(body?.vendedor_id ?? body?.vend_id ?? body?.vendId ?? ofRow?.vendedor_id ?? ofRow?.vend_id ?? ofRow?.vendId ?? '').trim();
    const valorOf = Number(body?.valor_total ?? body?.valor_venda ?? ofRow?.valor_total ?? ofRow?.valor_venda ?? 0);
    console.log('[COMISSAO] vendedorId:', vendedorId, 'valorOf:', valorOf);
    if (!vendedorId || !(valorOf > 0)) return;
    const { data: vend } = await supabase.from('vendedores').select('*').eq('id', vendedorId).maybeSingle();
    let perc = Number(vend?.comissao_pct ?? vend?.comissao ?? vend?.comissaoPct ?? 0);
    console.log('[OF COMISSAO] vendedorId:', vendedorId, 'valorOf:', valorOf, 'comissao%:', perc);
    if (!(perc > 0)) return;
    const valorComissao = valorOf * (perc / 100);
    const vendNome = String(vend?.nome || '').trim();
    const numero = body?.of ?? body?.numero ?? ofRow?.of ?? ofRow?.numero ?? '';
    await supabase.from('historico_acoes').insert([{
      tipo_acao: 'comissao_of',
      descricao: `Comissão OF #${numero || ''}: ${vendNome || ''} — R$ ${valorComissao.toFixed(2)} (${perc}% de R$ ${valorOf.toFixed(2)})`,
      usuario: req.usuario?.nome || 'sistema',
      data_hora: new Date().toISOString()
    }]);
  } catch (e) {}
}

async function _maybeBaixaAutomaticaChapasOF(req, body, ofRow) {
  try {
    if (body && body._estoqueJaBaixadoCriacao) return;
    const chapaId = String(body?.chapa_id ?? body?.chapaId ?? body?.chp ?? ofRow?.chapa_id ?? ofRow?.chapaId ?? ofRow?.chp ?? '').trim();
    const qtdChapas = Math.trunc(Number(body?.qtd_chapas ?? body?.qtdChapas ?? body?.qchp ?? 0) || 0);
    console.log('[OF BAIXA CHAPAS] chapaId:', chapaId, 'qtdChapas:', qtdChapas);
    if (!chapaId || !(qtdChapas > 0)) return;
    const table = await _chapasPreferV2Table();
    if (!table) return;
    const { data: chapa, error: e1 } = await supabase.from(table).select('*').eq('id', chapaId).maybeSingle();
    if (e1 || !chapa) return;
    const canonChapa = _chapasCanonicalFromAny(chapa, table);

    const ofNumero = body?.of ?? body?.numero ?? ofRow?.of ?? ofRow?.numero ?? null;
    const cliRef = body?.cliId ?? body?.cli_id ?? body?.cliente_id ?? ofRow?.cliId ?? ofRow?.cli_id ?? ofRow?.cliente_id ?? '';
    const empId = body?.emp_id ?? body?.empId ?? ofRow?.emp_id ?? ofRow?.empId ?? 'E1';
    const usuario = req?.usuario?.nome || 'sistema';

    if (table === 'chapas_estoque_v2') {
      const obs = `Saída automática - OF #${ofNumero || ''} · Cliente: ${cliRef || ''}`.trim();
      const origemId = ofNumero ? String(ofNumero) : (ofRow?.id ? String(ofRow.id) : null);
      const movRes = await _chapasMovimentarV2Rpc({
        chapa_id: chapaId,
        tipo: 'saida',
        quantidade: qtdChapas,
        nf: body?.nf || null,
        obs,
        origem: 'of',
        origem_id: origemId,
        usuario,
        emp_id: empId || null,
      });
      if (movRes?.error) {
        if (_chapasMovRpcIsSaldoInsuficiente(movRes.error)) {
          console.warn('[OF BAIXA CHAPAS] saldo insuficiente:', movRes.error?.message || movRes.error);
          return;
        }
        return;
      }
      cacheClearPrefix('chapas_estoque:');
      const desc = `Estoque chapas: SAIDA -${qtdChapas} · ${canonChapa.nome || ''} · ${canonChapa.fornecedor || ''} · ${canonChapa.nomenclatura || ''} · ${canonChapa.tamanho || ''}${ofNumero ? (' · OF #' + String(ofNumero)) : ''}`.trim();
      await _chapasLogAcao(req, 'estoque_saida', desc);
      return;
    }

    const qtdAtual = Math.trunc(Number(canonChapa.quantidade || 0) || 0);
    const qtdNova = Math.max(0, qtdAtual - qtdChapas);
    const updPayload = { qtd: qtdNova };
    const upd = await supabase.from(table).update(updPayload).eq('id', chapaId);
    if (upd.error) return;
    cacheClearPrefix('chapas_estoque:');
  } catch (e) {}
}

function _parseFluxoAny(v){
  if(Array.isArray(v)) return v.map(x=>String(x||'').trim()).filter(Boolean);
  if(typeof v === 'string'){
    const s = v.trim();
    if(!s) return [];
    try{
      const p = JSON.parse(s);
      if(Array.isArray(p)) return p.map(x=>String(x||'').trim()).filter(Boolean);
    }catch(_){}
    return [s].filter(Boolean);
  }
  return [];
}

const MAQUINAS_VALIDAS_NOMES = [
  'CORTE VINCO ROTATIVA',
  'IMP 01', 'IMP 02', 'IMP 03', 'IMP 04', 'IMP 05',
];

function _ofPickFluxoNames(of){
  try{
    let f = of?.fluxo_maquinas ?? of?.maq ?? [];
    if(typeof f === 'string'){
      const raw = String(f||'').trim();
      if(!raw) f = [];
      else { try{ f = JSON.parse(raw || '[]'); }catch(_){ f = _parseFluxoAny(raw); } }
    }
    if(!Array.isArray(f)) f = [];
    return f.map((x)=>{
      if(x && typeof x === 'object'){
        const n = x.nome ?? x.maquina ?? x.name ?? x.value ?? x.label ?? '';
        return String(n||'').trim();
      }
      return String(x||'').trim();
    }).filter(Boolean);
  }catch(_){
    return [];
  }
}

function _ofPickMaqAtualName(of){
  try{
    const f = _ofPickFluxoNames(of);
    if(!f.length) return '';
    const idx = Number(of?.maquina_atual_index ?? 0) || 0;
    return String(f[Math.min(Math.max(0, idx), f.length - 1)] || f[0] || '').trim();
  }catch(_){
    return '';
  }
}

async function _autoPickSugestaoMaquinaNome(body){
  try{
    if(!supabase) return { ok:false, skipped:'supabase_not_configured' };
    const comp = Number(body?.comprimento_mm ?? body?.caixa_comprimento ?? body?.caixaComprimento ?? body?.comprimento ?? 0) || 0;
    const larg = Number(body?.largura_mm ?? body?.caixa_largura ?? body?.caixaLargura ?? body?.largura ?? 0) || 0;
    const alt = Number(body?.altura_mm ?? body?.caixa_altura ?? body?.caixaAltura ?? body?.altura ?? 0) || 0;
    const onda = String(body?.onda ?? body?.of_onda ?? body?.onda_caixa ?? '').trim();
    if(!(comp > 0 && larg > 0)) return { ok:false, skipped:'sem_medidas' };

    const { data: maquinas, error } = await supabase
      .from('maquinas')
      .select('id,nome,col,puxada_min,puxada_max,boca_max,ativa,ordem')
      .eq('ativa', true)
      .order('ordem', { ascending: true })
      .limit(50);
    if (error || !Array.isArray(maquinas) || !maquinas.length) {
      return { ok: false, skipped: 'sem_maquinas' };
    }
    const maquinasAtivas = maquinas.filter(m => {
      const nome = String(m?.nome || m?.col || '').trim().toUpperCase();
      if (!m || m.ativa !== true) return false;
      if (!nome || nome === 'NULL') return false;
      return MAQUINAS_VALIDAS_NOMES.some(v => nome === String(v).toUpperCase() || nome.includes(String(v).toUpperCase()));
    });
    if (!maquinasAtivas.length) {
      return { ok: false, skipped: 'sem_maquinas_ativas' };
    }

    const folgaPuxada = 20;
    const folgaBoca = 15;
    const desenvolvimento = comp + (alt * 2) + folgaPuxada;
    const boca = larg + (alt * 2) + folgaBoca;

    const getRealLimits = (m) => {
      let pMin = Number(m?.puxada_min) || 0;
      let pMax = Number(m?.puxada_max) || 9999;
      if (pMin > pMax && pMax > 0) [pMin, pMax] = [pMax, pMin];
      const bMax = Number(m?.boca_max) || 9999;
      return { pMin, pMax, bMax };
    };

    try{
      console.log('[SUGESTAO MAQ DEBUG]', {
        comp, larg, alt,
        desenvolvimento,
        boca,
        maquinasAtivas: (maquinasAtivas || []).map(m => {
          const { pMin, pMax, bMax } = getRealLimits(m);
          const devOk = desenvolvimento >= pMin && desenvolvimento <= pMax;
          const bocaOk = boca <= bMax;
          return {
            nome: m.nome,
            puxada_min: m.puxada_min,
            puxada_max: m.puxada_max,
            boca_max: m.boca_max,
            devOk,
            bocaOk,
          };
        })
      });
    }catch(_){}

    const compat = (maquinasAtivas || []).filter((m)=>{
      const { pMin, pMax, bMax } = getRealLimits(m);
      const devOk = desenvolvimento >= pMin && desenvolvimento <= pMax;
      const bocaOk = boca <= bMax;
      return devOk && bocaOk;
    }).map((m)=>({ id:m.id, nome:String(m.nome||'').trim() })).filter((m)=>m.nome);

    const maquinasCompativeis = compat.length > 0 ? compat : (maquinasAtivas || []).map((m)=>({ id:m.id, nome:String(m.nome||'').trim() })).filter(m=>m.nome);

    const statusNotIn = '("Concluído","Concluido","Cancelada","Cancelado","Pedido Pronto")';
    const { data: ofsRaw } = await supabase
      .from('ofs')
      .select('id,status,fluxo_maquinas,maq,maquina_atual_index,deleted_at')
      .is('deleted_at', null)
      .not('status', 'in', statusNotIn)
      .limit(5000);
    const ofs = Array.isArray(ofsRaw) ? ofsRaw : [];
    const filaMap = new Map();
    const cand = new Set(maquinasCompativeis.map(x=>String(x.nome)));
    ofs.forEach((o)=>{
      const mk = String(_ofPickMaqAtualName(o) || '').trim();
      if(!mk || !cand.has(mk)) return;
      filaMap.set(mk, (filaMap.get(mk) || 0) + 1);
    });

    const dt30 = new Date(Date.now() - 30*24*60*60*1000).toISOString().slice(0,10);
    const { data: perdasRaw } = await supabase
      .from('caixas_perdidas')
      .select('id,of_id,qtd_perdida,maquina_perda,maquina,maquina_nome,data,created_at')
      .gte('data', dt30)
      .limit(5000);
    const perdas = Array.isArray(perdasRaw) ? perdasRaw : [];
    const ofIds = [...new Set(perdas.map(p=>String(p?.of_id||'').trim()).filter(Boolean))];
    const ofQtdMap = new Map();
    for(let i=0;i<ofIds.length;i+=200){
      const chunk = ofIds.slice(i,i+200);
      const { data: ofsP } = await supabase
        .from('ofs')
        .select('id,qtd,qtd_produzida,quantidade')
        .in('id', chunk)
        .limit(200);
      (Array.isArray(ofsP)?ofsP:[]).forEach((x)=>{
        const id = String(x?.id||'').trim();
        if(!id) return;
        const qtd = Number(x?.qtd_produzida ?? x?.qtd ?? x?.quantidade ?? 0) || 0;
        ofQtdMap.set(id, qtd);
      });
    }
    const perdaAgg = new Map();
    const pickMaq = (p)=>{
      const a = String(p?.maquina_perda||'').trim();
      const b = String(p?.maquina_nome||'').trim();
      const c = String(p?.maquina||'').trim();
      return a || b || c;
    };
    perdas.forEach((p)=>{
      const mk = String(pickMaq(p) || '').trim();
      if(!mk || !cand.has(mk)) return;
      const lost = Math.trunc(Number(p?.qtd_perdida||0) || 0);
      const prod = ofQtdMap.get(String(p?.of_id||'').trim()) || 0;
      const cur = perdaAgg.get(mk) || { lost:0, prod:0 };
      cur.lost += lost;
      cur.prod += Math.trunc(Number(prod)||0);
      perdaAgg.set(mk, cur);
    });
    const lossRate = (mk)=>{
      const a = perdaAgg.get(mk) || { lost:0, prod:0 };
      const lost = Number(a.lost||0) || 0;
      const prod = Number(a.prod||0) || 0;
      if(prod > 0) return lost / prod;
      return lost > 0 ? 1 : 0;
    };

    const ranked = maquinasCompativeis.map((m)=>{
      const fila = Math.trunc(Number(filaMap.get(m.nome) || 0) || 0);
      const taxa = lossRate(m.nome);
      const penal = taxa > 0.05 ? 1000 : 0;
      return { ...m, fila, taxa_perda: taxa, penalidade: penal };
    });
    ranked.sort((a,b)=>{
      if((a.penalidade||0) !== (b.penalidade||0)) return (a.penalidade||0) - (b.penalidade||0);
      if((a.fila||0) !== (b.fila||0)) return (a.fila||0) - (b.fila||0);
      if((a.taxa_perda||0) !== (b.taxa_perda||0)) return (a.taxa_perda||0) - (b.taxa_perda||0);
      return String(a.nome).localeCompare(String(b.nome));
    });
    const melhor = ranked[0];
    if(!melhor || !melhor.nome) return { ok:false, skipped:'sem_melhor' };
    return { ok:true, nome: melhor.nome, fila: melhor.fila, taxa_perda: melhor.taxa_perda, penalidade: melhor.penalidade };
  }catch(e){
    return { ok:false, skipped:'erro', error: String(e?.message || e) };
  }
}

async function _autoSugerirMaquinaParaOF(body, created){
  try{
    const fluxoBody = _parseFluxoAny(body?.fluxo_maquinas ?? body?.fluxoMaquinas ?? body?.maq ?? body?.maquinas ?? []);
    const fluxoCreated = _parseFluxoAny(created?.fluxo_maquinas ?? created?.maq ?? []);
    if(fluxoBody.length || fluxoCreated.length) return { ok:false, skipped:'ja_tem_maquina' };
    if(!supabase) return { ok:false, skipped:'supabase_not_configured' };

    const src = { ...(created||{}), ...(body||{}) };
    const comp = Number(src?.comprimento_mm ?? src?.caixa_comprimento ?? src?.caixaComprimento ?? src?.comprimento ?? 0) || 0;
    const larg = Number(src?.largura_mm ?? src?.caixa_largura ?? src?.caixaLargura ?? src?.largura ?? 0) || 0;
    const alt  = Number(src?.altura_mm ?? src?.caixa_altura ?? src?.caixaAltura ?? src?.altura ?? 0) || 0;
    if(!(comp > 0 && larg > 0 && alt > 0)) return { ok:false, skipped:'sem_medidas' };

    const { data: maquinas, error } = await supabase
      .from('maquinas')
      .select('id,nome,col,puxada_min,puxada_max,boca_max,ativa,ordem')
      .eq('ativa', true)
      .order('ordem', { ascending: true })
      .limit(50);

    if (error || !Array.isArray(maquinas) || !maquinas.length) {
      return { ok: false, skipped: 'sem_maquinas' };
    }

    const maquinasAtivas = maquinas.filter(m => {
      const nome = String(m.nome || m.col || '').trim().toUpperCase();
      if (!m || m.ativa !== true) return false;
      if (!nome) return false;
      return MAQUINAS_VALIDAS_NOMES.some(v => nome === String(v).toUpperCase() || nome.includes(String(v).toUpperCase()));
    });

    if (!maquinasAtivas.length) {
      return { ok: false, skipped: 'sem_maquinas_ativas' };
    }

    const folgaPuxada = 20;
    const folgaBoca = 15;
    const desenvolvimento = comp + (alt * 2) + folgaPuxada;
    const boca = larg + (alt * 2) + folgaBoca;

    console.log('[SUGESTAO MAQ]', {
      comp, larg, alt, desenvolvimento, boca,
      total_maquinas: maquinasAtivas.length,
      maquinas: maquinasAtivas.map(m => ({ nome: m.nome, pmin: m.puxada_min, pmax: m.puxada_max, bmax: m.boca_max })),
    });

    const getRealLimits = (m) => {
      let pMin = Number(m?.puxada_min) || 0;
      let pMax = Number(m?.puxada_max) || 9999;
      if (pMin > pMax && pMax > 0) [pMin, pMax] = [pMax, pMin];
      const bMax = Number(m?.boca_max) || 9999;
      return { pMin, pMax, bMax };
    };

    const compat = maquinasAtivas.filter(m => {
      const { pMin, pMax, bMax } = getRealLimits(m);
      const devOk = desenvolvimento >= pMin && desenvolvimento <= pMax;
      const bocaOk = boca <= bMax;
      return devOk && bocaOk;
    });

    const maquinasParaFila = compat.length > 0 ? compat : maquinasAtivas;
    console.log('[SUGESTAO MAQ] compat:', compat.length, 'fallback:', compat.length === 0);

    const statusNotIn = '("Concluído","Concluido","Cancelada","Cancelado","Pedido Pronto")';
    const filas = await Promise.all(maquinasParaFila.map(async (m) => {
      try {
        const nomeMaq = String(m.nome || m.col || '').trim();
        const { count, error: eCount } = await supabase
          .from('ofs')
          .select('id', { count: 'exact', head: true })
          .contains('fluxo_maquinas', [nomeMaq])
          .not('status', 'in', statusNotIn)
          .is('deleted_at', null);
        return { ...m, fila: eCount ? 999 : Math.trunc(Number(count || 0)) };
      } catch(_) {
        return { ...m, fila: 999 };
      }
    }));

    filas.sort((a, b) =>
      (Number(a.fila || 0) - Number(b.fila || 0)) ||
      String(a.nome || a.col || '').localeCompare(String(b.nome || b.col || ''))
    );

    const melhor = filas[0];
    if (!melhor) return { ok: false, skipped: 'sem_melhor' };

    const nomeMelhor = String(melhor.nome || melhor.col || '').trim();
    if (!nomeMelhor) return { ok: false, skipped: 'nome_vazio' };

    const updPayload = {
      fluxo_maquinas: [nomeMelhor],
      maq: JSON.stringify([nomeMelhor]),
      maquina_atual_index: 0
    };
    const upd = await supabase
      .from('ofs')
      .update(updPayload)
      .eq('id', created?.id)
      .select()
      .maybeSingle();

    if (upd?.error) return { ok: false, skipped: 'falha_update', error: upd.error.message };

    return {
      ok: true,
      nome: nomeMelhor,
      updated: upd?.data || null,
      compat_count: compat.length,
      fallback_usado: compat.length === 0,
    };
  }catch(e){
    return { ok:false, skipped:'erro', error: String(e?.message || e) };
  }
}

app.post('/api/ofs', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    const empId = await resolverEmpresaId(req);
    if (!empId) return res.status(400).json({ ok: false, error: 'Empresa não identificada' });
    const body = req.body || {};
    let filtered = ofPayloadFiltrado(body);
    filtered.empresa_id = empId;
    if (filtered.emp_id === undefined || filtered.emp_id === '') filtered.emp_id = empId;
    filtered = await _preencherCamposCriticosOF({ ...(body || {}), ...(filtered || {}) });
    filtered = ofPayloadFiltrado(filtered);
    filtered.empresa_id = empId;
    if (filtered.emp_id === undefined || filtered.emp_id === '') filtered.emp_id = empId;
    delete filtered.id;
    if ((filtered.of == null || String(filtered.of || '').trim() === '') && (filtered.numero == null || String(filtered.numero || '').trim() === '')) {
      try {
        const proximoNumeroOF = async (empresa_id) => {
          const { data, error } = await supabase
            .from('ofs')
            .select('numero')
            .eq('empresa_id', empresa_id)
            .order('created_at', { ascending: false })
            .limit(200);
          if (error) throw error;
          let maior = 0;
          (data || []).forEach((o) => {
            const n = parseInt(String(o?.numero || '').replace(/\D/g, ''), 10) || 0;
            if (n > maior) maior = n;
          });
          return maior + 1;
        };

        const { data: last } = await supabase
          .from('ofs')
          .select('seq,of,numero')
          .order('seq', { ascending: false })
          .limit(1)
          .maybeSingle();
        const lastSeq = Math.trunc(Number(last?.seq || 0) || 0);
        const nextSeq = lastSeq > 0 ? (lastSeq + 1) : 1;
        filtered.seq = nextSeq;
        let numeroEmpresa = null;
        try { numeroEmpresa = await proximoNumeroOF(empId); } catch (_) { numeroEmpresa = null; }
        for (let i = 0; i < 5; i += 1) {
          const cand = String((numeroEmpresa != null ? numeroEmpresa : nextSeq) + i);
          const { data: exists } = await supabase
            .from('ofs')
            .select('id')
            .eq('empresa_id', empId)
            .eq('numero', cand)
            .limit(1);
          if (Array.isArray(exists) && exists.length) continue;
          filtered.of = cand;
          filtered.numero = cand;
          break;
        }
      } catch (_) {}
    }
    {
      const parseItens = (v) => {
        if (Array.isArray(v)) return v;
        if (typeof v === 'string') { try { const p = JSON.parse(v || '[]'); return Array.isArray(p) ? p : []; } catch (_) { return []; } }
        return [];
      };
      const merged = { ...(body || {}), ...(filtered || {}) };
      const cliId = String(merged.cli_id ?? merged.cliId ?? merged.cliente_id ?? '').trim();
      const vendId = String(merged.vendid ?? merged.vendedor ?? merged.vendedor_id ?? merged.vendedorId ?? merged.vendId ?? merged.vend_id ?? '').trim();
      const qtd = Number(merged.qtd ?? merged.quantidade ?? merged.qtd_pedida ?? 0) || 0;
      const ent = String(merged.ent ?? merged.data_entrega ?? '').slice(0, 10);
      const itens = parseItens(merged.itens ?? body.itens);
      const item0 = (Array.isArray(itens) ? itens : [])[0] || {};
      const prod = String(merged.prodDesc ?? merged.descricao ?? merged.produto ?? item0.desc ?? item0.descricao ?? '').trim();
      const total = Number(merged.total ?? merged.valor_total ?? merged.valor_venda ?? 0) || 0;
      const vunitItens = Math.max(0, ...(Array.isArray(itens) ? itens : []).map((it) => Number(it?.valor_unitario ?? it?.vunit ?? 0) || 0));
      const vunit = Number(merged.preco ?? merged.valor_unitario ?? merged.vl_unit ?? 0) || ((vunitItens > 0) ? vunitItens : ((qtd > 0) ? (total / qtd) : 0));
      const clinome = String(merged.clinome ?? merged.cliNome ?? merged.cliente_nome ?? '').trim();
      const vendedor = String(merged.vendedor ?? merged.vendNome ?? '').trim();
      console.log('[OF CREATE] campos críticos:', { clinome, vendedor, vendid: vendId, preco: vunit, qtd, total });
      if (!clinome) console.warn('[OF CREATE] AVISO: clinome vazio!');
      if (!vendedor) console.warn('[OF CREATE] AVISO: vendedor vazio!');
      if (!(vunit > 0)) console.warn('[OF CREATE] AVISO: preco zero!');
      const missing = [];
      if (!cliId) missing.push('cliente');
      if (!vendId) missing.push('vendedor');
      if (!(qtd > 0)) missing.push('quantidade');
      if (!prod) missing.push('produto/modelo');
      if (!ent) missing.push('data de entrega');
      if (!(vunit > 0)) missing.push('valor unitário');
      if (missing.length) {
        return res.status(400).json({ ok: false, error: 'Campos obrigatórios: ' + missing.join(', '), missing });
      }
    }
    console.debug('[OF SAVE]', req.method, req.params.id || 'novo', JSON.stringify(Object.keys(body)));
    const createdRes = await ofsInsertWithRetry(ofIn(filtered));
    if (createdRes.error) throw createdRes.error;
    let created = createdRes.data;
    await logAuditoria('ofs', 'INSERT', created?.id, null, created, req);
    await _maybeRegistrarComissaoOF(req, body, created);
    await _maybeBaixaAutomaticaChapasOF(req, body, created);
    try {
      const cliId = String(body?.cli_id || body?.cliId || created?.cli_id || created?.cliId || created?.cliente_id || '').trim();
      const vendId = String(
        body?.vendedor_id || body?.vendId || body?.vend_id ||
        created?.vendedor_id || created?.vendId || created?.vend_id || ''
      ).trim();
      if (cliId && vendId) {
        await supabase
          .from('clientes')
          .update({ vendedor_id: vendId })
          .eq('id', cliId)
          .is('vendedor_id', null);
        cacheClearPrefix('clientes_');
      }
    } catch (_) {}
    try {
      const itens = Array.isArray(body?.itens) ? body.itens : [];
      for (const item of itens) {
        const itemChapaId = String(item?.chapa_id ?? item?.chapaId ?? '').trim();
        const itemQtdChapas = Math.trunc(Number(item?.qtd_chapas ?? item?.qtdChapas ?? item?.qchp ?? 0) || 0);
        if (!itemChapaId || !(itemQtdChapas > 0)) continue;
        await _maybeBaixaAutomaticaChapasOF(req, {
          chapa_id: itemChapaId,
          qtd_chapas: itemQtdChapas,
          of: created?.of ?? body?.of ?? '',
          numero: created?.numero ?? body?.numero ?? '',
          emp_id: body?.emp_id ?? body?.empId ?? created?.emp_id ?? created?.empId ?? 'E1',
          _estoqueJaBaixadoCriacao: false,
        }, created);
      }
    } catch (_) {}
    try{
      const sug = await _autoSugerirMaquinaParaOF(body, created);
      if(sug && sug.ok && sug.updated) created = sug.updated;
    }catch(_){}
    const warnings = (createdRes && Array.isArray(createdRes.ignoredColumns) && createdRes.ignoredColumns.length)
      ? { ignored_columns: createdRes.ignoredColumns.slice() }
      : null;
    _clearOfsCaches();
    return res.json({ ok: true, data: created, ...(warnings ? { warnings } : {}) });
  } catch (e) {
    _logApiError('OFS POST', req, e, { bodyKeys: Object.keys(req.body || {}), bodySize: _safeJson(req.body || {}).length });
    return res.status(500).json({ ok: false, error: String(e?.message || e), rid: req._rid || null });
  }
});

app.get('/api/ofs/buscar', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    const numeroRaw = String(req.query?.numero || '').trim();
    const clienteRaw = String(req.query?.cliente || req.query?.search || '').trim();
    const statusRaw = String(req.query?.status || '').trim().toLowerCase();
    const includeSomenteAbertas = !statusRaw || statusRaw.includes('aberto');
    if (clienteRaw) {
      const { data: clientes, error: cliErr } = await supabase
        .from('clientes')
        .select('id,nome,rs,vendedor_id')
        .or('nome.ilike.%' + clienteRaw + '%,rs.ilike.%' + clienteRaw + '%')
        .limit(100);
      if (cliErr) return res.status(400).json({ ok: false, error: String(cliErr.message || cliErr) });

      const clientesArr = Array.isArray(clientes) ? clientes : [];
      const clienteIds = clientesArr.map((c) => String(c?.id || '').trim()).filter(Boolean);
      if (!clienteIds.length) return ok(res, []);

      let query = supabase
        .from('ofs')
        .select('*')
        .in('cli_id', clienteIds)
        .order('created_at', { ascending: false })
        .limit(50);
      if (includeSomenteAbertas) {
        query = query.not('status', 'in', '("Concluído","Concluída","Concluido","Concluida","Cancelada","Cancelado","Pedido Pronto")');
      }
      const { data: ofsRows, error: ofsErr } = await query;
      if (ofsErr) return res.status(400).json({ ok: false, error: String(ofsErr.message || ofsErr) });

      const lista = await _enriquecerRespostaOFs(Array.isArray(ofsRows) ? ofsRows : []);
      return ok(res, lista);
    }

    if (!numeroRaw) return res.status(400).json({ ok: false, error: 'numero obrigatório' });

    const joinKeys = ['cli_id', 'cliente_id', 'cliId'];
    let data = null;
    let lastError = null;

    for (const key of joinKeys) {
      const r = await supabase
        .from('ofs')
        .select(`*,cliente:clientes!${key}(nome,vendedor_id,vendedor:vendedores!vendedor_id(nome))`)
        .ilike('numero', `%${numeroRaw}%`)
        .order('created_at', { ascending: false })
        .limit(10);
      if (!r.error) { data = r.data; break; }
      lastError = r.error;
      const msg = String(r.error?.message || '');
      if (msg.includes('relationship') || msg.includes('schema cache') || msg.includes('Could not find a relationship')) continue;
      break;
    }

    if (!data) {
      const { data: data2, error: e2 } = await supabase
        .from('ofs')
        .select('*')
        .ilike('numero', `%${numeroRaw}%`)
        .order('created_at', { ascending: false })
        .limit(10);
      if (e2) return res.status(400).json({ ok: false, error: String(e2.message || e2) });
      data = data2 || [];
    }

    const lista = Array.isArray(data) ? data : (data ? [data] : []);
    if (!lista.length) return res.status(404).json({ ok: false, error: 'OF não encontrada' });

    const of = lista[0] || null;
    if (!of) return res.status(404).json({ ok: false, error: 'OF não encontrada' });

    let cliNome = '';
    let vendNome = '';
    let vendedorId = null;
    try {
      const clienteJoin = of.cliente && typeof of.cliente === 'object' ? of.cliente : null;
      const vendNested = clienteJoin?.vendedor && typeof clienteJoin.vendedor === 'object' ? clienteJoin.vendedor : null;
      cliNome = String(clienteJoin?.nome || of.cliNome || of.clinome || of.cliente_nome || of.cliente || '').trim();
      vendNome = String(vendNested?.nome || of.vendNome || of.vendedor_nome || of.vendedor || '').trim();
      vendedorId = clienteJoin?.vendedor_id || of.vendedor_id || of.vendid || of.vendId || null;
    } catch (_) {}

    const isUuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
    if (vendNome && isUuid(String(vendNome).trim())) vendNome = '';
    if ((!vendNome || isUuid(String(vendNome || '').trim())) && vendedorId && isUuid(String(vendedorId || '').trim())) {
      try {
        const { data: vend } = await supabase.from('vendedores').select('nome').eq('id', String(vendedorId)).maybeSingle();
        if (vend?.nome) vendNome = String(vend.nome).trim();
      } catch (_) {}
    }

    const [out] = await _enriquecerRespostaOFs([{
      ...of,
      cliNome: cliNome || of?.cliNome || of?.cliente_nome || of?.cliente || '',
      cliente_nome: cliNome || of?.cliNome || of?.cliente_nome || of?.cliente || '',
      clinome: cliNome || of?.cliNome || of?.cliente_nome || of?.cliente || '',
      vendNome: vendNome || of?.vendNome || of?.vendedor_nome || of?.vendedor || '',
      vendedor_nome: vendNome || of?.vendNome || of?.vendedor_nome || of?.vendedor || '',
      vendedor: vendNome || of?.vendNome || of?.vendedor_nome || of?.vendedor || '',
      vendedor_id: vendedorId || of?.vendedor_id || of?.vendid || of?.vendId || null,
      ent: of?.ent ?? of?.data_entrega ?? null,
      dia: of?.dia ?? null,
    }]);
    return ok(res, out || of);
  } catch (e) { return res.status(500).json({ ok: false, error: String(e?.message || e) }); }
});

app.get('/api/ofs/busca', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    const q = String(req.query?.q || '').trim();
    const termos = q.split(',').map((t) => String(t || '').trim()).filter(Boolean);
    if (!termos.length) return res.json([]);

    let query = supabase
      .from('ofs')
      .select('id, of, clinome, vendedor, vendid, preco, total, qtd, qtd_produzida, ent, dia, status, empresa_id')
      .is('deleted_at', null)
      .limit(50);

    const filtros = termos.flatMap((t) => {
      const txt = String(t || '').trim();
      if (!txt) return [];
      return [`of.eq.${txt}`, `clinome.ilike.%${txt}%`];
    }).join(',');

    query = query.or(filtros);
    const { data, error } = await query;
    if (error) return res.status(500).json({ error: String(error.message || error) });
    const enriquecidas = await _enriquecerRespostaOFs(Array.isArray(data) ? data : []);
    return res.json(enriquecidas);
  } catch (e) {
    return res.status(500).json({ error: String(e.message || e) });
  }
});

app.get('/api/ofs/:id', authMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    if (!id) return res.status(400).json({ ok: false, error: 'id obrigatório' });
    const joinKeys = ['cli_id', 'cliente_id', 'cliId'];
    let data = null;
    for (const key of joinKeys) {
      const r = await supabase
        .from('ofs')
        .select(`*,cliente:clientes!${key}(nome,vendedor_id,vendedor:vendedores!vendedor_id(nome))`)
        .eq('id', id)
        .maybeSingle();
      if (!r.error) { data = r.data; break; }
      const msg = String(r.error?.message || '');
      if (msg.includes('relationship') || msg.includes('schema cache') || msg.includes('Could not find a relationship')) continue;
      break;
    }
    if (!data) {
      const r = await supabase.from('ofs').select('*').eq('id', id).maybeSingle();
      if (r.error) return res.status(500).json({ ok: false, error: r.error.message });
      data = r.data;
    }
    if (!data) return res.status(404).json({ ok: false, error: 'OF não encontrada' });

    const clienteJoin = data.cliente && typeof data.cliente === 'object' ? data.cliente : null;
    const vendNested = clienteJoin?.vendedor && typeof clienteJoin.vendedor === 'object' ? clienteJoin.vendedor : null;
    const { cliente, ...rest } = data;

    let cliNome = clienteJoin?.nome || data.cliNome || data.clinome || '';
    let vendNome = vendNested?.nome || data.vendNome || data.vendedor_nome || data.vendedor || '';
    let vendedorId = clienteJoin?.vendedor_id || data.vendedor_id || data.vendId || null;
    const isUuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
    if (vendNome && isUuid(String(vendNome).trim())) vendNome = '';
    if (!vendedorId && vendNome && isUuid(String(vendNome).trim())) vendedorId = String(vendNome).trim();

    if (!cliNome || !vendNome) {
      const cliId = String(data.cli_id || data.cliId || data.cliente_id || '').trim();
      if (cliId) {
        const { data: cli } = await supabase
          .from('clientes')
          .select('nome,vendedor_id,vendedor:vendedores!vendedor_id(nome)')
          .eq('id', cliId)
          .maybeSingle();
        if (cli) {
          cliNome = cliNome || cli.nome || '';
          vendedorId = vendedorId || cli.vendedor_id || null;
          const v = cli.vendedor && typeof cli.vendedor === 'object' ? cli.vendedor : null;
          vendNome = vendNome || v?.nome || '';
        }
      }
    }
    if ((!vendNome || isUuid(String(vendNome || '').trim())) && vendedorId && isUuid(String(vendedorId || '').trim())) {
      try {
        const { data: vend } = await supabase.from('vendedores').select('nome').eq('id', String(vendedorId)).maybeSingle();
        if (vend?.nome) vendNome = String(vend.nome).trim();
      } catch (_) {}
    }
    if (vendNome && isUuid(String(vendNome).trim())) vendNome = '';
    return ok(res, { ...rest, cliNome, vendNome, vendedor_id: vendedorId, vendedor_nome: vendNome });
  } catch (e) { return res.status(500).json({ ok: false, error: String(e.message || e) }); }
});

app.put('/api/ofs/:id', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    let body = filterOfsUpdateWhitelist(normalizeOfUpdateBody(req.body || {}));
    body = filterOfsUpdateWhitelist(await _preencherCamposCriticosOF(body, { onlyClinome: true }));
    try { console.log('[OF PATCH] payload recebido:', JSON.stringify(req.body || {}).substring(0, 300)); } catch (_) {}
    try { console.log('[OF PATCH] campos após whitelist:', Object.keys(body || {})); } catch (_) {}
    if (body.qtd !== undefined) body.qtd = Number(body.qtd);
    if (body.qtd_produzida !== undefined) body.qtd_produzida = Number(body.qtd_produzida);
    if (body.qtd_perdida !== undefined) body.qtd_perdida = Number(body.qtd_perdida);
    if (body.qtd_pedida !== undefined) body.qtd_pedida = Number(body.qtd_pedida);
    if (body.total !== undefined) body.total = Number(body.total);
    if (body.valor_total !== undefined) body.valor_total = Number(body.valor_total);
    if (body.valor_venda !== undefined) body.valor_venda = Number(body.valor_venda);
    if (body.preco !== undefined) {
      body.preco = Number(body.preco);
    }
    const { data, error } = await supabase
      .from('ofs').update(body).eq('id', req.params.id).select().single();
    if (error) return res.status(400).json({ ok: false, error: error.message });
    _clearOfsCaches();
    res.json({ ok: true, data: _sanitizeOfImagesForResponse(data) });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});
app.delete('/api/ofs/:id', authMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    const now = new Date().toISOString();
    let antes = null;
    try {
      const r0 = await supabase.from('ofs').select('*').eq('id', id).maybeSingle();
      antes = r0?.data || null;
    } catch (_) {}
    const payload = { deleted_at: now, updated_at: now };
    let { data, error } = await supabase.from('ofs').update(payload).eq('id', id).select('*').maybeSingle();
    if (error) {
      const msg = String(error.message || error);
      if (msg.toLowerCase().includes('deleted_at') && (msg.includes('column') || msg.includes('Could not find'))) {
        await deleteOne('ofs', id);
        await logAuditoria('ofs', 'DELETE', id, antes, null, req);
        _clearOfsCaches();
        return ok(res, true);
      }
      throw error;
    }
    try {
      const vendId = String(data?.vendedor_id || '').trim();
      const val = Number(data?.valor_total || data?.valor_venda || 0);
      const numero = data?.of ?? data?.numero ?? '';
      if (vendId && val > 0) {
        await supabase.from('historico_acoes').insert([{
          tipo_acao: 'comissao_cancelada',
          descricao: `Comissão cancelada - OF #${numero || ''} cancelada/excluída`,
          usuario: req.usuario?.nome || 'sistema',
          data_hora: new Date().toISOString()
        }]);
      }
    } catch (_) {}
    await logAuditoria('ofs', 'DELETE', id, antes, null, req);
    _clearOfsCaches();
    return res.json({ ok: true, data });
  } catch (e) { bad(res, e.message); }
});

