app.get('/api/chat/nao-lidas', authMiddleware, async (req, res) => {
  try {
    const userId = String(req.usuario?.id || req.usuario?.sub || '').trim();
    const { count } = await supabase.from('chat_mensagens')
      .select('id', { count: 'exact', head: true })
      .eq('para_usuario', userId)
      .eq('lida', false);
    res.json({ ok: true, total: Math.trunc(Number(count || 0)) });
  } catch (e) {
    try { console.error('[chat/nao-lidas]', String(e?.message || e)); } catch (_) {}
    res.json({ ok: true, total: 0 });
  }
});

app.get('/api/avisos', authMiddleware, async (req, res) => {
  try {
    const userId = String(req.usuario?.id || req.usuario?.sub || '').trim();
    const { data, error } = await supabase.from('avisos_usuarios')
      .select('*')
      .or(`para_usuario.eq.${userId},para_usuario.is.null`)
      .eq('lido', false)
      .order('created_at', { ascending: false });
    if (error) throw error;
    res.json({ ok: true, avisos: data || [] });
  } catch (e) {
    try { console.error('[avisos]', String(e?.message || e)); } catch (_) {}
    res.json({ ok: true, avisos: [] });
  }
});

app.post('/api/avisos', authMiddleware, async (req, res) => {
  try {
    const { mensagem, para_usuario } = req.body || {};
    if (!mensagem) return res.status(400).json({ ok: false, error: 'mensagem obrigatória' });
    const userId = String(req.usuario?.id || req.usuario?.sub || '').trim();
    const nome = String(req.usuario?.nome || req.usuario?.email || 'Sistema').trim() || 'Sistema';
    const { data, error } = await supabase.from('avisos_usuarios').insert({
      de_usuario: userId || null,
      de_nome: nome,
      para_usuario: para_usuario || null,
      mensagem: String(mensagem),
      lido: false,
    }).select().single();
    if (error) throw error;
    res.json({ ok: true, aviso: data });
  } catch (e) { res.status(500).json({ ok: false, error: String(e.message || e) }); }
});

app.patch('/api/avisos/:id/lido', authMiddleware, async (req, res) => {
  try {
    const { error } = await supabase
      .from('avisos_usuarios')
      .update({ lido: true })
      .eq('id', req.params.id);
    if (error) throw error;
    res.json({ ok: true });
  } catch (e) {
    console.error('[avisos/lido]', e.message);
    res.json({ ok: true });
  }
});

app.post('/api/of/upload', authMiddleware, ofUpload.single('file'), async (req, res) => {
  try {
    const f = req.file || null;
    if (!f) return res.status(400).json({ ok: false, error: 'Arquivo obrigatório' });
    const ext = path.extname(f.originalname || '').toLowerCase();
    const filename = `of/${Date.now()}-${Math.random().toString(36).slice(2)}${ext}`;
    const { error } = await supabase.storage
      .from('uploads')
      .upload(filename, f.buffer, { contentType: f.mimetype, upsert: false });
    if (error) throw error;
    const { data: urlData } = supabase.storage.from('uploads').getPublicUrl(filename);
    return ok(res, { url: urlData?.publicUrl || '' });
  } catch (e) { return res.status(500).json({ ok: false, error: String(e.message || e) }); }
});

app.get('/api/relatorio/vendedor', authMiddleware, async (req, res) => {
  try {
    console.log('[RELATORIO VENDEDOR] iniciando, query:', req.query);

    const mes = String(req.query.mes || '').trim();
    const de = String(req.query.de || '').trim();
    const ate = String(req.query.ate || '').trim();
    const empId = String(req.query.empId || '').trim();

    const monthBounds = (m) => {
      const s = String(m || '').slice(0, 7);
      const [yy, mm] = s.split('-').map((x) => Number(x));
      if (!(yy > 1900 && mm >= 1 && mm <= 12)) return { ini: '', fim: '' };
      const dtIni = new Date(yy, mm - 1, 1);
      const dtFim = new Date(yy, mm, 0);
      return { ini: dtIni.toISOString().slice(0, 10), fim: dtFim.toISOString().slice(0, 10) };
    };

    const baseCols = [
      'id', 'of', 'numero', 'status', 'dia', 'created_at',
      'cli_id',
      'vendedor_id',
      'vendId', 'vend_id', 'vendedorId',
      'vendedor', 'vendedor_nome', 'vendNome',
      'cliente_id',
      'valor_total', 'valor_venda',
      'qtd', 'descricao',
      'emp_id', 'deleted_at',
    ];
    const selectWithRetry = async (table, cols, build) => {
      let useCols = cols.slice();
      for (let tentativa = 0; tentativa < 5; tentativa++) {
        const q = build(supabase.from(table).select(useCols.join(',')));
        const r = await q.limit(150);
        if (!r.error) return { data: r.data || [], usedCols: useCols };
        const msg = String(r.error.message || r.error);
        console.error('[RELATORIO VENDEDOR] erro query:', msg);
        const col = msg.match(/Could not find the '([^']+)' column/)?.[1];
        if (col && useCols.includes(col)) {
          useCols = useCols.filter((c) => c !== col);
          continue;
        }
        throw r.error;
      }
      throw new Error('Falha ao buscar OFs após tentativas');
    };

    const { ini: iniMes, fim: fimMes } = mes ? monthBounds(mes) : { ini: '', fim: '' };
    const diaIni = mes ? iniMes : (de || '');
    const diaFim = mes ? fimMes : (ate || '');

    let ofs = [];
    try {
      const r1 = await selectWithRetry('ofs', baseCols, (q) => {
        let qq = q;
        if (empId) qq = qq.eq('emp_id', empId);
        if (diaIni && diaFim) qq = qq.gte('dia', diaIni).lte('dia', diaFim);
        return qq;
      });
      ofs = r1.data || [];
    } catch (error) {
      console.error('[RELATORIO VENDEDOR] erro query ofs:', String(error?.message || error));
      const cols2 = [
        'id', 'of', 'numero', 'status', 'dia', 'created_at',
        'cli_id',
        'vendedor_id',
        'vendId', 'vend_id', 'vendedorId',
        'vendedor', 'vendedor_nome', 'vendNome',
        'cliente_id',
        'valor_total', 'valor_venda',
        'qtd', 'descricao',
        'emp_id',
      ];
      const r2 = await selectWithRetry('ofs', cols2, (q) => {
        let qq = q;
        if (empId) qq = qq.eq('emp_id', empId);
        if (mes && iniMes && fimMes) qq = qq.gte('created_at', iniMes).lte('created_at', fimMes);
        return qq;
      });
      ofs = r2.data || [];
    }

    ofs = (ofs || []).filter((of) => {
      if (!of) return false;
      const st = String(of.status || '').toLowerCase();
      if (st === 'cancelada' || st === 'cancelado') return false;
      if (of.deleted_at) return false;
      return true;
    });

    console.log('[RELATORIO VENDEDOR] OFs após filtro:', ofs.length);
    console.log('[COMISSAO DEBUG]', {
      totalOfs: ofs?.length,
      semVendedor: ofs?.filter((o) => !o.vendedor_id && !o.vendId && !o.vend_id).length,
      camposVendedor: ofs?.[0] ? Object.keys(ofs[0]).filter((k) => String(k || '').toLowerCase().includes('vend')) : [],
    });

    const cliIds = Array.from(new Set((ofs || []).map((o) => String(o?.cli_id || o?.cliente_id || '').trim()).filter(Boolean)));
    const mapCli = {};
    const cliVendMap = new Map();
    if (cliIds.length) {
      try {
        const { data: clis, error: ec } = await supabase
          .from('clientes')
          .select('id,nome,vendedor_id,vendId,vend_id')
          .in('id', cliIds)
          .limit(2000);
        if (!ec) {
          (clis || []).forEach((c) => {
            if (c && c.id) mapCli[String(c.id)] = c.nome || '';
            const vid = String(c?.vendedor_id || c?.vendId || c?.vend_id || '').trim();
            if (c?.id && vid) cliVendMap.set(String(c.id), vid);
          });
        }
      } catch (_) {}
    }

    const { data: vendedores, error: ev } = await supabase.from('vendedores').select('id,nome,comissao_pct');
    if (ev) throw ev;
    const mapVend = {};
    const vendNomeMap = new Map();
    (vendedores || []).forEach((v) => {
      mapVend[String(v.id)] = { id: v.id, nome: v.nome || '', pct: Number(v.comissao_pct || 0) };
      if (v && v.id) vendNomeMap.set(String(v.id), String(v.nome || '').trim());
    });

    console.log('[RELATORIO VENDEDOR] vendedores:', Object.keys(mapVend).length);

    const getVendedorId = (of) => {
      return String(of?.vendedor_id || of?.vendId || of?.vend_id || of?.vendedorId || '').trim();
    };
    const getVendedorNome = (of, vendMap) => {
      const vid = getVendedorId(of);
      if (vid && vendMap?.has?.(vid)) return vendMap.get(vid);
      const nome = String(of?.vendedor_nome || of?.vendNome || of?.vendedor || '').trim();
      return nome || null;
    };

    const grupos = {};
    let totalGeral = 0;
    let totalComissao = 0;

    for (const ofRow of ofs) {
      const cliId = String(ofRow?.cli_id || ofRow?.cliente_id || '').trim();
      const vendIdDireto = getVendedorId(ofRow);
      const vendDoCliente = cliId ? (cliVendMap.get(cliId) || '') : '';
      const vendIdFinal = String(vendIdDireto || vendDoCliente || '').trim();
      const vendNomeDireto = vendIdFinal ? '' : (getVendedorNome(ofRow, vendNomeMap) || '');
      const grupoKey = vendIdFinal || (vendNomeDireto ? `nome:${vendNomeDireto}` : 'sem_vendedor');

      const vend = vendIdFinal ? mapVend[vendIdFinal] : null;
      const vendNome = vend ? vend.nome : (vendNomeDireto || 'Sem vendedor');
      const pct = vend ? vend.pct : 0;
      const valor = Number(ofRow.valor_total || ofRow.valor_venda || 0);
      const comissaoOf = valor * (pct / 100);
      const dtOf = ofRow.dia || (ofRow.created_at ? String(ofRow.created_at).slice(0, 10) : '');

      if (!grupos[grupoKey]) {
        grupos[grupoKey] = {
          vendedorId: vendIdFinal || null,
          vendedor: vendNome,
          comissaoPct: pct,
          pedidos: 0,
          qtdTotal: 0,
          valorTotal: 0,
          comissaoTotal: 0,
          ofs: [],
        };
      }

      grupos[grupoKey].pedidos++;
      grupos[grupoKey].qtdTotal += Number(ofRow.qtd || 0);
      grupos[grupoKey].valorTotal += valor;
      grupos[grupoKey].comissaoTotal += comissaoOf;
      grupos[grupoKey].ofs.push({
        numero: ofRow.of || ofRow.numero || '',
        cliente: mapCli[String(cliId || '').trim()] || (cliId || ''),
        descricao: ofRow.descricao || '',
        qtd: Number(ofRow.qtd || 0),
        valor,
        comissaoPct: pct,
        comissaoValor: comissaoOf,
        dataPedido: dtOf,
        status: ofRow.status || '',
      });

      totalGeral += valor;
      totalComissao += comissaoOf;
    }

    const resultado = Object.values(grupos)
      .map((g) => ({ ...g, ticketMedio: g.pedidos > 0 ? g.valorTotal / g.pedidos : 0 }))
      .sort((a, b) => b.valorTotal - a.valorTotal);

    console.log('[RELATORIO VENDEDOR] grupos:', resultado.length);

    return res.json({
      vendedores: resultado,
      totalGeral,
      totalComissao,
      totalPedidos: ofs.length,
    });
  } catch (e) {
    console.error('[RELATORIO VENDEDOR] ERRO FATAL:', e?.message, e?.stack);
    return res.status(500).json({ error: String(e.message || e) });
  }
});

app.get('/api/relatorios/clientes-inativos', authMiddleware, async (req, res) => {
  try {
    const empresa_id = await _resolveEmpresaUuid(req);
    if (!empresa_id) return res.status(400).json({ ok: false, error: 'empresa_id não encontrado' });
    const diasMinimo = Math.max(1, parseInt(String(req.query.dias || '30'), 10) || 30);

    const { data: ofs, error: ofsErr } = await supabase
      .from('ofs')
      .select('cliente_id,created_at,data_entrega')
      .eq('empresa_id', empresa_id)
      .not('cliente_id', 'is', null)
      .order('created_at', { ascending: false })
      .limit(10000);
    if (ofsErr) throw ofsErr;

    const ultimoPorCliente = {};
    (Array.isArray(ofs) ? ofs : []).forEach((of) => {
      const cid = of?.cliente_id;
      if (!cid) return;
      const dt = of?.created_at ? new Date(of.created_at) : null;
      if (!dt || Number.isNaN(dt.getTime())) return;
      if (!ultimoPorCliente[cid] || dt > ultimoPorCliente[cid]) ultimoPorCliente[cid] = dt;
    });

    const hoje = new Date();
    const clientesInativos = Object.entries(ultimoPorCliente)
      .map(([cliente_id, data]) => ({
        cliente_id,
        ultimo_pedido: (data instanceof Date) ? data.toISOString() : String(data),
        dias_sem_pedido: Math.floor((hoje.getTime() - (data instanceof Date ? data.getTime() : new Date(data).getTime())) / 86400000),
      }))
      .filter((c) => Number(c.dias_sem_pedido || 0) >= diasMinimo)
      .sort((a, b) => Number(b.dias_sem_pedido || 0) - Number(a.dias_sem_pedido || 0));

    if (!clientesInativos.length) return res.json({ ok: true, data: [] });

    const ids = clientesInativos.map((c) => String(c.cliente_id || '').trim()).filter(Boolean);
    const { data: clientes, error: cliErr } = await supabase
      .from('clientes')
      .select('id,nome,telefone,tel,email,cidade,uf,cnpj,documento,endereco,ativo,vendedor_id')
      .in('id', ids)
      .limit(10000);
    if (cliErr) throw cliErr;

    const clientesMap = {};
    (Array.isArray(clientes) ? clientes : []).forEach((c) => { if (c?.id) clientesMap[String(c.id)] = c; });

    const vendIds = Array.from(new Set((Array.isArray(clientes) ? clientes : []).map((c) => String(c?.vendedor_id || '').trim()).filter(_isUuid))).slice(0, 10000);
    const vendMap = {};
    if (vendIds.length) {
      const { data: usrs, error: usrErr } = await supabase.from('usuarios').select('id,nome,email').in('id', vendIds).limit(10000);
      if (usrErr) throw usrErr;
      (Array.isArray(usrs) ? usrs : []).forEach((u) => { if (u?.id) vendMap[String(u.id)] = u; });
    }

    const resultado = clientesInativos.map((c) => {
      const dados = clientesMap[String(c.cliente_id)] || {};
      const vend = dados?.vendedor_id ? vendMap[String(dados.vendedor_id)] : null;
      return {
        cliente_id: c.cliente_id,
        ultimo_pedido: c.ultimo_pedido,
        dias_sem_pedido: c.dias_sem_pedido,
        nome: dados.nome || '—',
        telefone: dados.telefone || dados.tel || '—',
        email: dados.email || '—',
        cidade: dados.cidade || '—',
        uf: dados.uf || '—',
        cnpj: dados.cnpj || dados.documento || '—',
        vendedor: vend?.nome || '—',
        vendedor_email: vend?.email || '—',
        ativo: dados.ativo,
      };
    });

    return res.json({ ok: true, data: resultado });
  } catch (e) {
    console.error('[CLIENTES INATIVOS]', e);
    return res.status(500).json({ ok: false, error: String(e?.message || e) });
  }
});

app.get('/api/relatorio/resultado-empresas', authMiddleware, async (req, res) => {
  try {
    const dataInicio = String(req.query.dataInicio || '').trim();
    const dataFim = String(req.query.dataFim || '').trim();
    const empId = String(req.query.empId || '').trim();

    let q = supabase
      .from('ofs')
      .select([
        'id',
        'empresa_id',
        'emp_id',
        'valor_total',
        'valor_venda',
        'qtd',
        'quantidade',
        'qtd_produzida',
        'qtd_perdida',
        'qtd_chapas',
        'chapa_id',
        'status',
        'data_conclusao',
        'deleted_at',
      ].join(','))
      .eq('status', 'Concluído')
      .is('deleted_at', null);

    if (dataInicio) q = q.gte('data_conclusao', dataInicio);
    if (dataFim) q = q.lte('data_conclusao', dataFim + 'T23:59:59');
    if (empId) q = q.eq('emp_id', empId);

    const { data: ofs, error } = await q.limit(5000);
    if (error) return res.status(500).json({ ok: false, error: String(error.message || error) });

    const chapaIds = Array.from(new Set((ofs || [])
      .map((o) => String(o?.chapa_id || '').trim())
      .filter(Boolean)));

    const precoChapa = {};
    if (chapaIds.length > 0) {
      const tableCh = await _chapasPreferV2Table();
      const cols = tableCh === 'chapas_estoque_v2' ? 'id,valor_unitario' : 'id,val,valor_unitario';
      const r = await supabase.from(tableCh).select(cols).in('id', chapaIds);
      if (!r.error) {
        (r.data || []).forEach((row) => {
          const v = tableCh === 'chapas_estoque_v2'
            ? Number(row.valor_unitario || 0)
            : Number((row.valor_unitario ?? row.val) || 0);
          precoChapa[String(row.id)] = Number.isFinite(v) ? v : 0;
        });
      }
    }

    const empresas = {};
    (ofs || []).forEach((of) => {
      const emp = String(of.emp_id || of.empresa_id || 'SEM EMPRESA');
      if (!empresas[emp]) {
        empresas[emp] = {
          emp_id: emp,
          total_ofs: 0,
          valor_faturado: 0,
          caixas_produzidas: 0,
          caixas_perdidas: 0,
          total_chapas: 0,
          valor_chapas: 0,
          lucro_estimado: 0,
        };
      }

      const valor = Number(of.valor_total ?? of.valor_venda ?? 0) || 0;
      const caixasProd = Number(of.qtd_produzida ?? of.qtd ?? of.quantidade ?? 0) || 0;
      const caixasPerd = Number(of.qtd_perdida ?? 0) || 0;
      const qtdCh = Number(of.qtd_chapas ?? 0) || 0;
      const chapaId = String(of.chapa_id || '').trim();
      const vUnitCh = chapaId ? (Number(precoChapa[chapaId] || 0) || 0) : 0;
      const custoCh = qtdCh * vUnitCh;

      empresas[emp].total_ofs += 1;
      empresas[emp].valor_faturado += valor;
      empresas[emp].caixas_produzidas += caixasProd;
      empresas[emp].caixas_perdidas += caixasPerd;
      empresas[emp].total_chapas += qtdCh;
      empresas[emp].valor_chapas += custoCh;
      empresas[emp].lucro_estimado += (valor - custoCh);
    });

    const out = Object.values(empresas).sort((a, b) => String(a.emp_id).localeCompare(String(b.emp_id)));
    return res.json({ ok: true, data: out });
  } catch (e) {
    return res.status(500).json({ ok: false, error: String(e.message || e) });
  }
});

async function _selectCompatRows(table, columns, applyQuery) {
  let cur = String(columns || '*');
  for (let tentativa = 0; tentativa < 16; tentativa += 1) {
    let q = supabase.from(table).select(cur);
    if (typeof applyQuery === 'function') q = applyQuery(q) || q;
    const { data, error } = await q;
    if (!error) return { data: Array.isArray(data) ? data : [], error: null, columns: cur };
    const msg = String(error.message || error || '');
    const m1 = msg.match(/Could not find the '([^']+)' column/i);
    const m2 = msg.match(/column\s+"([^"]+)"\s+does not exist/i);
    const col = (m1 && m1[1]) || (m2 && m2[1]) || null;
    if (!col) return { data: null, error, columns: cur };
    const parts = cur.split(',').map((s) => String(s || '').trim()).filter(Boolean);
    const next = parts.filter((c) => c !== col);
    if (!next.length || next.length === parts.length) return { data: null, error, columns: cur };
    cur = next.join(',');
  }
  return { data: null, error: { message: 'Falha ao selecionar colunas compatíveis de ' + table }, columns: cur };
}

function _normalizarOperadoresCaixa(row) {
  const extrairOp = (op) => {
    if (op == null) return '';
    if (typeof op === 'string' || typeof op === 'number') return String(op || '').trim();
    if (Array.isArray(op)) {
      return op.map(extrairOp).filter(Boolean).join(', ');
    }
    if (typeof op === 'object') {
      return String(
        op.nome ??
        op.name ??
        op.label ??
        op.value ??
        op.operador ??
        op.operador_nome ??
        op.operadorName ??
        op.operador_id ??
        op.id ??
        ''
      ).trim();
    }
    return '';
  };
  const bruto = row?.operadores ?? row?.operadores_conclusao;
  let lista = [];
  try {
    if (Array.isArray(bruto)) lista = bruto;
    else if (typeof bruto === 'string') {
      const txt = String(bruto || '').trim();
      if (txt) {
        if (txt[0] === '[') {
          const parsed = JSON.parse(txt);
          if (Array.isArray(parsed)) lista = parsed;
        } else {
          lista = txt.split(/[,;|]+/g);
        }
      }
    }
  } catch (_) {}
  lista = (Array.isArray(lista) ? lista : []).map(extrairOp).filter(Boolean);
  if (!lista.length) {
    const candidatos = [
      row?.operador_display,
      row?.operador_principal,
      row?.operador_nome,
      row?.operador,
      row?.operador_conclusao,
    ].map(extrairOp).filter(Boolean);
    lista = candidatos.length ? candidatos : [];
  }
  return Array.from(new Set(lista));
}

let _caixasOperadorColumnEnsured = false;
let _caixasOperadorColumnEnsurePromise = null;
function _caixasPerdidasOperadorSql() {
  return "ALTER TABLE caixas_perdidas ADD COLUMN IF NOT EXISTS operador text;";
}
async function _ensureCaixasPerdidasOperadorColumn() {
  if (_caixasOperadorColumnEnsured) return true;
  if (_caixasOperadorColumnEnsurePromise) return _caixasOperadorColumnEnsurePromise;
  _caixasOperadorColumnEnsurePromise = (async () => {
    let hasColumn = false;
    try {
      const probe = await supabase.from('caixas_perdidas').select('operador').limit(1);
      if (!probe?.error) hasColumn = true;
      else {
        const msg = String(probe.error?.message || probe.error || '').toLowerCase();
        if (!(msg.includes('could not find the') || msg.includes('does not exist') || msg.includes('column'))) {
          throw probe.error;
        }
      }
    } catch (e) {
      const msg = String(e?.message || e || '').toLowerCase();
      if (!(msg.includes('could not find the') || msg.includes('does not exist') || msg.includes('column'))) throw e;
    }
    if (!hasColumn) {
      try {
        const rpc = await supabase.rpc('exec_sql', { sql: _caixasPerdidasOperadorSql() });
        if (rpc?.error) {
          try { console.warn('[caixas_perdidas][operador] exec_sql:', rpc.error.message || rpc.error); } catch (_) {}
        } else {
          hasColumn = true;
        }
      } catch (e) {
        try { console.warn('[caixas_perdidas][operador] ensure falhou:', e?.message || e); } catch (_) {}
      }
    }
    _caixasOperadorColumnEnsured = !!hasColumn;
    _caixasOperadorColumnEnsurePromise = null;
    return _caixasOperadorColumnEnsured;
  })();
  return _caixasOperadorColumnEnsurePromise;
}

function _isUuidText(v) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v || '').trim());
}

async function _carregarMapaPessoasCaixa(ids) {
  const lista = Array.from(new Set((Array.isArray(ids) ? ids : []).map((id) => String(id || '').trim()).filter(Boolean)));
  const map = new Map();
  if (!lista.length) return map;
  for (let i = 0; i < lista.length; i += 200) {
    const lote = lista.slice(i, i + 200);
    try {
      const { data: ops } = await supabase.from('operadores').select('id,nome').in('id', lote);
      (Array.isArray(ops) ? ops : []).forEach((op) => {
        const id = String(op?.id || '').trim();
        const nome = String(op?.nome || '').trim();
        if (id && nome) map.set(id, nome);
      });
    } catch (_) {}
    try {
      const { data: users } = await supabase.from('usuarios').select('id,nome,email').in('id', lote);
      (Array.isArray(users) ? users : []).forEach((usr) => {
        const id = String(usr?.id || '').trim();
        const nome = String(usr?.nome || usr?.email || '').trim();
        if (id && nome && !map.has(id)) map.set(id, nome);
      });
    } catch (_) {}
  }
  return map;
}

function _resolverPessoaCaixa(v, pessoasMap) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  if (!(_isUuidText(raw)) && !pessoasMap?.has(raw)) return raw;
  return String((pessoasMap && pessoasMap.get(raw)) || raw).trim();
}

function _caixasNormKey(v) {
  try {
    return String(v || '')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+/g, ' ');
  } catch (_) {
    return String(v || '').trim().toLowerCase();
  }
}

function _caixasMachineCandidates(row, ofData, maquinasMap) {
  const base = [
    row?.maquina_id,
    ofData?.maquina_id,
    row?.maquina_nome,
    row?.maquina,
    row?.maquina_perda,
    ofData?.maquina,
    ofData?.maquina_atual,
    ofData?.maquina_agendada,
    ofData?.maq,
  ];
  const resolved = _resolverNomeMaquinaPassagem({
    maquina_id: row?.maquina_id || ofData?.maquina_id || '',
    maquina_nome: row?.maquina_nome || row?.maquina || row?.maquina_perda || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
    maquina: row?.maquina || row?.maquina_perda || row?.maquina_nome || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
  }, maquinasMap);
  if (resolved) base.push(resolved);
  return Array.from(new Set(base.map((v) => _caixasNormKey(v)).filter(Boolean)));
}

function _caixasParsePerdasPorMaquina(value) {
  try {
    if (Array.isArray(value)) return value.filter((item) => item && typeof item === 'object');
    if (typeof value === 'string') {
      const txt = String(value || '').trim();
      if (!txt) return [];
      const parsed = JSON.parse(txt);
      if (Array.isArray(parsed)) return parsed.filter((item) => item && typeof item === 'object');
    }
  } catch (_) {}
  return [];
}

function _resolverOperadorDaPerda(row, ofData, pessoasMap, maquinasMap) {
  const rowMachineKeys = _caixasMachineCandidates(row, ofData, maquinasMap);
  const perdasDetalhadas = _caixasParsePerdasPorMaquina(ofData?.perdas_por_maquina);
  const operadoresDetalhe = [];
  perdasDetalhadas.forEach((item) => {
    const itemMachineKeys = [
      item?.maquina_id,
      item?.maquina_nome,
      item?.maquina,
      item?.maquina_perda,
      item?.nome_maquina,
      _resolverNomeMaquinaPassagem({
        maquina_id: item?.maquina_id || '',
        maquina_nome: item?.maquina_nome || item?.maquina || item?.maquina_perda || item?.nome_maquina || '',
        maquina: item?.maquina || item?.maquina_perda || item?.maquina_nome || item?.nome_maquina || '',
      }, maquinasMap),
    ].map((v) => _caixasNormKey(v)).filter(Boolean);
    const sameMachine = !rowMachineKeys.length || !itemMachineKeys.length || itemMachineKeys.some((key) => rowMachineKeys.includes(key));
    if (!sameMachine) return;
    const ops = _normalizarOperadoresCaixa({
      operadores: item?.operadores ?? item?.operadores_conclusao ?? item?.operador ?? item?.operador_nome ?? item?.operador_conclusao ?? item?.usuario,
      operadores_conclusao: item?.operadores_conclusao,
      operador: item?.operador,
      operador_nome: item?.operador_nome,
      operador_conclusao: item?.operador_conclusao,
      operador_display: item?.operador_display,
      operador_principal: item?.operador_principal,
    }).map((op) => _resolverPessoaCaixa(op, pessoasMap)).filter(Boolean);
    operadoresDetalhe.push.apply(operadoresDetalhe, ops);
  });
  const detalhe = Array.from(new Set(operadoresDetalhe.filter(Boolean)));
  if (detalhe.length) return detalhe;

  const conclusao = _normalizarOperadoresCaixa({
    operadores: ofData?.operadores_conclusao,
    operadores_conclusao: ofData?.operadores_conclusao,
    operador: ofData?.operador_conclusao,
    operador_conclusao: ofData?.operador_conclusao,
  }).map((op) => _resolverPessoaCaixa(op, pessoasMap)).filter(Boolean);
  if (conclusao.length) return Array.from(new Set(conclusao));

  const usuario = _resolverPessoaCaixa(row?.usuario, pessoasMap);
  if (usuario) return [usuario];

  return ['Sem operador registrado'];
}

function _caixasPerdidasDashboardVazio(mesRef = '') {
  return {
    ok: true,
    resumo_mes_atual: {
      total_caixas: 0,
      valor_total: 0,
      total_ocorrencias: 0,
      mes_referencia: mesRef || '',
      toneladas_perdidas: 0,
      toneladas_sem_dados: 0,
    },
    comparacao_mes_anterior: {
      total_caixas: 0,
      valor_total: 0,
      variacao_caixas_pct: 0,
      variacao_valor_pct: 0,
    },
    ranking_maquinas: [],
    ranking_operadores: [],
    detalhamento: [],
  };
}

async function _listarCaixasPerdidasEnriquecidas(req) {
  try { await _ensureCaixasPerdidasOperadorColumn(); } catch (_) {}
  const baseCols = [
    'id', 'of_id', 'of_numero', 'produto', 'cliente', 'valor_unitario', 'qtd_perdida', 'valor_perdido',
    'data', 'mes_referencia', 'emp_id', 'empresa_id', 'usuario', 'usuario_conclusao', 'concluido_por', 'obs', 'created_at',
    'maquina', 'maquina_nome', 'maquina_id', 'maquina_perda', 'quantidade', 'caixas_perdidas',
    'operadores', 'operadores_conclusao', 'operador', 'operador_nome', 'operador_principal', 'operador_conclusao', 'turno'
  ].join(',');
  const ofId = String(req.query.of_id || req.query.ofId || '').trim();
  const tabelas = ['caixas_perdidas', 'caixas_perdas', 'perdas_producao'];
  let cpRows = { data: [], error: null };
  let achouTabela = false;
  for (const t of tabelas) {
    const r = await _selectCompatRows(t, baseCols, (q) => {
      let out = q.order('created_at', { ascending: false });
      if (ofId) out = out.eq('of_id', ofId);
      return out;
    });
    if (r?.error) {
      const msg = String(r.error?.message || r.error || '').toLowerCase();
      if (msg.includes('does not exist') || msg.includes('not exist') || msg.includes('could not find')) continue;
      throw r.error;
    }
    achouTabela = true;
    cpRows = r;
    if (Array.isArray(r?.data) && r.data.length) break;
  }
  if (!achouTabela) return [];

  const rows = Array.isArray(cpRows.data) ? cpRows.data : [];
  _debugRuntimeWrite({
    runId: 'pre-fix',
    hypothesisId: 'C',
    location: 'server.js:_listarCaixasPerdidasEnriquecidas',
    msg: '[DEBUG] caixas perdidas base carregada',
    data: { tabelaEncontrada: achouTabela, totalRows: rows.length, ofId },
  });
  const ofIds = Array.from(new Set(rows.map((r) => String(r?.of_id || '').trim()).filter(Boolean)));
  const ofNumeros = Array.from(new Set(rows.map((r) => String(r?.of_numero || '').trim()).filter(Boolean)));
  const ofsMap = new Map();

  if (ofIds.length) {
    for (let i = 0; i < ofIds.length; i += 200) {
      const lote = ofIds.slice(i, i + 200);
      const { data } = await supabase
        .from('ofs')
        .select('id,numero,cli_id,cliente,descricao,produto,prodDesc,data_conclusao,concluido_por,usuario_conclusao,operador_conclusao,operadores_conclusao,perdas_por_maquina,quantidade,qtd,valor_total,valor_venda,maq,maquina,maquina_atual,maquina_agendada,maquina_id')
        .in('id', lote);
      (Array.isArray(data) ? data : []).forEach((of) => {
        const id = String(of?.id || '').trim();
        if (id) ofsMap.set(id, of);
      });
    }
  }

  const numerosSemOf = ofNumeros.filter((numero) => {
    return !rows.some((r) => String(r?.of_id || '').trim() && String(r?.of_numero || '').trim() === numero);
  });
  if (numerosSemOf.length) {
    for (let i = 0; i < numerosSemOf.length; i += 200) {
      const lote = numerosSemOf.slice(i, i + 200);
      const { data } = await supabase
        .from('ofs')
        .select('id,numero,cli_id,cliente,descricao,produto,prodDesc,data_conclusao,concluido_por,usuario_conclusao,operador_conclusao,operadores_conclusao,perdas_por_maquina,quantidade,qtd,valor_total,valor_venda,maq,maquina,maquina_atual,maquina_agendada,maquina_id')
        .in('numero', lote);
      (Array.isArray(data) ? data : []).forEach((of) => {
        const numero = String(of?.numero || '').trim();
        if (numero) ofsMap.set('numero:' + numero, of);
      });
    }
  }

  const clienteIds = Array.from(new Set(rows.map((r) => {
    const ofData =
      ofsMap.get(String(r?.of_id || '').trim()) ||
      ofsMap.get('numero:' + String(r?.of_numero || '').trim()) ||
      null;
    return String(ofData?.cli_id || '').trim();
  }).filter(Boolean)));
  const clientesMap = new Map();
  if (clienteIds.length) {
    for (let i = 0; i < clienteIds.length; i += 200) {
      const lote = clienteIds.slice(i, i + 200);
      const { data } = await supabase.from('clientes').select('id,nome,rs').in('id', lote);
      (Array.isArray(data) ? data : []).forEach((cli) => {
        const id = String(cli?.id || '').trim();
        if (id) clientesMap.set(id, String(cli?.nome || cli?.rs || '').trim());
      });
    }
  }

  const maquinaIds = Array.from(new Set(rows.map((r) => String(r?.maquina_id || '').trim()).filter(Boolean)));
  const maquinasMap = new Map();
  if (maquinaIds.length) {
    const { data: maqs } = await supabase.from('maquinas').select('id,nome').in('id', maquinaIds);
    (Array.isArray(maqs) ? maqs : []).forEach((maq) => {
      const id = String(maq?.id || '').trim();
      if (id) maquinasMap.set(id, String(maq?.nome || '').trim());
    });
  }

  const pessoaIds = Array.from(new Set(rows.flatMap((row) => {
    const ofData =
      ofsMap.get(String(row?.of_id || '').trim()) ||
      ofsMap.get('numero:' + String(row?.of_numero || '').trim()) ||
      null;
    const opIds = _normalizarOperadoresCaixa(row).filter(_isUuidText);
    const ofOpIds = _normalizarOperadoresCaixa(ofData).filter(_isUuidText);
    const detalheOpIds = _caixasParsePerdasPorMaquina(ofData?.perdas_por_maquina).flatMap((item) => {
      return _normalizarOperadoresCaixa({
        operadores: item?.operadores ?? item?.operadores_conclusao ?? item?.operador ?? item?.operador_nome ?? item?.operador_conclusao ?? item?.usuario,
        operadores_conclusao: item?.operadores_conclusao,
        operador: item?.operador,
        operador_nome: item?.operador_nome,
        operador_conclusao: item?.operador_conclusao,
      }).filter(_isUuidText);
    });
    const outros = [
      row?.usuario_conclusao,
      row?.concluido_por,
      row?.usuario,
      row?.operador,
      row?.operador_nome,
      row?.operador_principal,
      ofData?.usuario_conclusao,
      ofData?.concluido_por,
      ofData?.operador_conclusao,
    ].map((v) => String(v || '').trim()).filter(_isUuidText);
    return opIds.concat(ofOpIds, detalheOpIds, outros);
  })));
  const pessoasMap = await _carregarMapaPessoasCaixa(pessoaIds);

  return rows.map((row) => {
    const ofData =
      ofsMap.get(String(row?.of_id || '').trim()) ||
      ofsMap.get('numero:' + String(row?.of_numero || '').trim()) ||
      null;
    const clienteNome =
      String(row?.cliente_nome || '').trim() ||
      clientesMap.get(String(ofData?.cli_id || '').trim()) ||
      String(row?.cliente || ofData?.cliente || '').trim() ||
      '—';
    const maquinaNome = _resolverNomeMaquinaPassagem({
      maquina_id: row?.maquina_id || ofData?.maquina_id || '',
      maquina_nome: row?.maquina_nome || row?.maquina || row?.maquina_perda || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
      maquina: row?.maquina || row?.maquina_perda || row?.maquina_nome || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
    }, maquinasMap) || 'Sem máquina';
    const quantidade = Number(row?.quantidade ?? row?.caixas_perdidas ?? row?.qtd_perdida ?? 0) || 0;
    const operadores = _resolverOperadorDaPerda(row, ofData, pessoasMap, maquinasMap);
    const concluidoPor = _resolverPessoaCaixa(row?.concluido_por || row?.usuario_conclusao || ofData?.concluido_por || row?.usuario, pessoasMap) || '—';
    return {
      ...row,
      of_numero: String(row?.of_numero || ofData?.numero || '').trim() || '—',
      cliente_nome: clienteNome,
      cliente: clienteNome,
      produto: String(row?.produto || ofData?.produto || ofData?.descricao || ofData?.prodDesc || '').trim() || '—',
      maquina: maquinaNome,
      maquina_nome: maquinaNome,
      quantidade,
      qtd_perdida: quantidade,
      operadores,
      operador: operadores[0] || 'Sem operador registrado',
      operador_display: operadores.join(', '),
      data: String(row?.data || row?.created_at || '').slice(0, 10),
      usuario: concluidoPor,
      usuario_conclusao: concluidoPor,
      turno: String(row?.turno || '').trim(),
      data_conclusao: String(row?.data_conclusao || ofData?.data_conclusao || '').slice(0, 10),
      concluido_por: concluidoPor,
      valor_unitario: Number(
        row?.valor_unitario ??
        (
          (Number(ofData?.quantidade ?? ofData?.qtd ?? 0) || 0) > 0
            ? ((Number(ofData?.valor_total ?? ofData?.valor_venda ?? 0) || 0) / (Number(ofData?.quantidade ?? ofData?.qtd ?? 0) || 1))
            : 0
        )
      ) || 0,
      valor_perdido: Number(
        row?.valor_perdido ??
        (
          (Number(row?.quantidade ?? row?.caixas_perdidas ?? row?.qtd_perdida ?? 0) || 0)
          * (
            Number(row?.valor_unitario ?? 0) || (
              (Number(ofData?.quantidade ?? ofData?.qtd ?? 0) || 0) > 0
                ? ((Number(ofData?.valor_total ?? ofData?.valor_venda ?? 0) || 0) / (Number(ofData?.quantidade ?? ofData?.qtd ?? 0) || 1))
                : 0
            )
          )
        )
      ) || 0,
    };
  });
}

