app.get('/api/caixas-perdidas/dashboard', authMiddleware, async (req, res) => {
  try {
    setNoCache(res);
    try { await _ensureCaixasPerdidasOperadorColumn(); } catch (_) {}

    const toArray = (v) => {
      if (Array.isArray(v)) return v.map((x) => String(x || '').trim()).filter(Boolean);
      if (typeof v === 'string') {
        const s = String(v || '').trim();
        if (!s) return [];
        try {
          const parsed = JSON.parse(s);
          if (Array.isArray(parsed)) return parsed.map((x) => String(x || '').trim()).filter(Boolean);
        } catch (_) {}
        return s.split(/[,;|/]+/g).map((x) => String(x || '').trim()).filter(Boolean);
      }
      return [];
    };

    let tabelaAtiva = null;
    for (const t of ['caixas_perdidas', 'caixas_perdas', 'perdas_producao']) {
      const { error } = await supabase.from(t).select('*').limit(1);
      if (!error) { tabelaAtiva = t; break; }
    }

    if (!tabelaAtiva) {
      return res.json({
        _debug: 'nenhuma tabela encontrada',
        detalhamento: [],
        resumo_mes_atual: { total_caixas: 0, valor_total: 0, total_ocorrencias: 0 },
        ranking_maquinas: [],
        ranking_operadores: [],
        comparacao_mes_anterior: {}
      });
    }

    const { data: todos } = await supabase
      .from(tabelaAtiva)
      .select('*')
      .order('created_at', { ascending: false })
      .limit(500);

    try { console.log('[CP] tabela:', tabelaAtiva, 'total:', todos?.length); } catch (_) {}
    try { if (todos?.[0]) console.log('[CP] campos:', Object.keys(todos[0])); } catch (_) {}
    try { if (todos?.[0]) console.log('[CP] primeiro_registro:', JSON.stringify(todos[0])); } catch (_) {}

    const parseRowDate = (row) => {
      const raw = row?.created_at || row?.data || row?.data_perda || row?.data_conclusao || null;
      if (!raw) return null;
      const dt = new Date(raw);
      return Number.isNaN(dt.getTime()) ? null : dt;
    };
    const matchMonthYear = (dt, month, year) => !!(dt && (dt.getMonth() + 1 === month) && dt.getFullYear() === year);
    const requestedPeriodo = String(req.query.periodo || '').trim().toLowerCase() || 'mes';
    let mes = parseInt(String(req.query.mes || ''), 10) || (new Date().getMonth() + 1);
    let ano = parseInt(String(req.query.ano || ''), 10) || new Date().getFullYear();
    const semFiltro = String(req.query.todos || '').trim().toLowerCase() === 'true' || requestedPeriodo === 'todos';
    const hojeRef = new Date();
    hojeRef.setHours(0, 0, 0, 0);
    const semanaIni = new Date(hojeRef);
    semanaIni.setDate(hojeRef.getDate() - ((hojeRef.getDay() + 6) % 7));
    const semanaFim = new Date(semanaIni);
    semanaFim.setDate(semanaIni.getDate() + 7);
    const filtrarPeriodo = (rows, periodo, month, year) => (rows || []).filter((r) => {
      const d = parseRowDate(r);
      if (!d) return true;
      if (periodo === 'hoje' || periodo === 'dia') return d >= hojeRef;
      if (periodo === 'semana') return d >= semanaIni && d < semanaFim;
      if (periodo === 'todos') return true;
      return matchMonthYear(d, month, year);
    });

    let dadosFiltrados = semFiltro ? (todos || []) : filtrarPeriodo(todos || [], requestedPeriodo, mes, ano);
    let fallbackMesRecente = false;
    if (!dadosFiltrados.length && !semFiltro && requestedPeriodo === 'mes') {
      const maisRecente = (todos || []).map((r) => ({ row: r, dt: parseRowDate(r) })).filter((item) => !!item.dt).sort((a, b) => b.dt - a.dt)[0] || null;
      if (maisRecente && maisRecente.dt) {
        mes = maisRecente.dt.getMonth() + 1;
        ano = maisRecente.dt.getFullYear();
        dadosFiltrados = filtrarPeriodo(todos || [], 'mes', mes, ano);
        fallbackMesRecente = true;
      }
    }
    _debugRuntimeWrite({
      runId: 'pre-fix',
      hypothesisId: 'C',
      location: 'server.js:/api/caixas-perdidas/dashboard',
      msg: '[DEBUG] dashboard caixas perdidas filtrado',
      data: {
        tabelaAtiva,
        periodo: requestedPeriodo,
        semFiltro,
        totalHistorico: Array.isArray(todos) ? todos.length : 0,
        totalFiltrado: Array.isArray(dadosFiltrados) ? dadosFiltrados.length : 0,
        mes,
        ano,
        fallbackMesRecente,
      },
    });

    const ofIds = Array.from(new Set((dadosFiltrados || []).map((r) => String(r?.of_id || r?.of_uuid || '').trim()).filter(Boolean)));
    const { data: ofsRows } = ofIds.length
      ? await supabase.from('ofs').select('id,numero,cli_id,valor_total,quantidade,qtd,descricao,produto,operador_conclusao,operadores_conclusao,perdas_por_maquina,usuario_conclusao,concluido_por,maq,maquina,maquina_atual,maquina_agendada,maquina_id,caixa_comprimento,caixa_largura,comprimento_mm,largura_mm,dim_comprimento,dim_largura,comprimento,largura,gramatura_id,gramatura,gramatura_nome').in('id', ofIds)
      : { data: [] };
    const ofsMap = Object.create(null);
    (ofsRows || []).forEach((of) => { ofsMap[String(of.id || '').trim()] = of; });

    const gramaturaIds = Array.from(new Set((ofsRows || []).map((of) => String(of?.gramatura_id || '').trim()).filter(Boolean)));
    const { data: gramaturasRows } = gramaturaIds.length
      ? await supabase.from('gramaturas').select('id,gramatura,nome').in('id', gramaturaIds)
      : { data: [] };
    const gramaturasMap = Object.create(null);
    (gramaturasRows || []).forEach((g) => {
      gramaturasMap[String(g?.id || '').trim()] = Number(g?.gramatura || 0) || 0;
    });

    const cliIds = Array.from(new Set((ofsRows || []).map((of) => String(of?.cli_id || '').trim()).filter(Boolean)));
    const { data: clientesRows } = cliIds.length
      ? await supabase.from('clientes').select('id,nome').in('id', cliIds)
      : { data: [] };
    const clientesMap = Object.create(null);
    (clientesRows || []).forEach((cli) => { clientesMap[String(cli.id || '').trim()] = String(cli.nome || '').trim(); });

    const maquinasMap = await _carregarMapaMaquinasPassagens((dadosFiltrados || []).map((r) => {
      const ofData = ofsMap[String(r?.of_id || r?.of_uuid || '').trim()] || null;
      return {
        maquina_id: r?.maquina_id || ofData?.maquina_id || '',
        maquina_nome: r?.maquina_nome || r?.maquina || r?.maquina_perda || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
        maquina: r?.maquina || r?.maquina_perda || r?.maquina_nome || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
      };
    }));

    const pessoaIds = Array.from(new Set((dadosFiltrados || []).flatMap((r) => {
      const ofData = ofsMap[String(r?.of_id || r?.of_uuid || '').trim()] || null;
      const ops = _normalizarOperadoresCaixa(r)
        .concat(_normalizarOperadoresCaixa(ofData))
        .concat(_caixasParsePerdasPorMaquina(ofData?.perdas_por_maquina).flatMap((item) => _normalizarOperadoresCaixa({
          operadores: item?.operadores ?? item?.operadores_conclusao ?? item?.operador ?? item?.operador_nome ?? item?.operador_conclusao ?? item?.usuario,
          operadores_conclusao: item?.operadores_conclusao,
          operador: item?.operador,
          operador_nome: item?.operador_nome,
          operador_conclusao: item?.operador_conclusao,
        })));
      const extras = [r?.usuario, r?.usuario_conclusao, r?.concluido_por, ofData?.usuario_conclusao, ofData?.concluido_por];
      return ops.concat(extras).map((v) => String(v || '').trim()).filter(_isUuidText);
    })));
    const pessoasMap = await _carregarMapaPessoasCaixa(pessoaIds);

    const parseDimMm = (src, keys) => {
      const arr = Array.isArray(keys) ? keys : [];
      for (const key of arr) {
        if (!src || !Object.prototype.hasOwnProperty.call(src, key)) continue;
        const v = Number(src[key] || 0) || 0;
        if (v > 0) return v;
      }
      return 0;
    };
    const resolveToneladasPerdidasItem = (ofData, qtdPerdida) => {
      const comprimentoMm = parseDimMm(ofData, ['comprimento_mm', 'caixa_comprimento', 'dim_comprimento', 'comprimento']);
      const larguraMm = parseDimMm(ofData, ['largura_mm', 'caixa_largura', 'dim_largura', 'largura']);
      const gramatura = Number(
        ofData?.gramatura ??
        gramaturasMap[String(ofData?.gramatura_id || '').trim()] ??
        0
      ) || 0;
      if (!(comprimentoMm > 0) || !(larguraMm > 0) || !(gramatura > 0) || !(qtdPerdida > 0)) return null;
      return ((comprimentoMm / 1000) * (larguraMm / 1000) * gramatura * qtdPerdida) / 1000000;
    };

    const enriquecidos = (dadosFiltrados || []).map((r) => {
      const ofId = String(r?.of_id || r?.of_uuid || '').trim();
      const ofData = ofId ? ofsMap[ofId] : null;
      const qtdPerdida = Number(r?.quantidade ?? r?.caixas_perdidas ?? r?.qtd_perdida ?? 0) || 0;
      const qtdOfBase = Number(ofData?.quantidade ?? ofData?.qtd ?? 0) || 0;
      const vu = Number(
        r?.valor_unitario ??
        (
          (Number(ofData?.valor_total || 0) > 0 && qtdOfBase > 0)
            ? (Number(ofData?.valor_total || 0) / qtdOfBase)
            : 0
        )
      ) || 0;
      const valorPerdido = Number(r?.valor_perdido ?? (vu * qtdPerdida)) || 0;
      const clienteNome = ofData?.cli_id ? (clientesMap[String(ofData.cli_id || '').trim()] || '') : '';
      const operadores = _resolverOperadorDaPerda(r, ofData, pessoasMap, maquinasMap);
      const concluidoPor = _resolverPessoaCaixa(r?.concluido_por || r?.usuario_conclusao || r?.usuario, pessoasMap) || '—';
      const dataRef = r?.created_at || r?.data || r?.data_perda || r?.data_conclusao || null;
      const maquinaNome = _resolverNomeMaquinaPassagem({
        maquina_id: r?.maquina_id || ofData?.maquina_id || '',
        maquina_nome: r?.maquina_nome || r?.maquina || r?.maquina_perda || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
        maquina: r?.maquina || r?.maquina_perda || r?.maquina_nome || ofData?.maquina || ofData?.maquina_atual || ofData?.maquina_agendada || ofData?.maq || '',
      }, maquinasMap) || 'Sem máquina';

      const toneladasPerdidasItem = resolveToneladasPerdidasItem(ofData, qtdPerdida);

      return {
        ...r,
        of_numero: ofData?.numero || r?.of_numero || '—',
        cliente_nome: clienteNome || r?.cliente_nome || r?.cliente || '—',
        cliente: clienteNome || r?.cliente_nome || r?.cliente || '—',
        produto: ofData?.descricao || r?.produto || '—',
        quantidade_perdida: qtdPerdida,
        valor_perdido: valorPerdido,
        maquina: maquinaNome,
        maquina_nome: maquinaNome,
        maquinas: maquinaNome && maquinaNome !== '—' ? [maquinaNome] : [],
        operadores,
        operador: operadores[0] || 'Sem operador registrado',
        operadores_nomes: operadores.join(', '),
        usuario: concluidoPor,
        usuario_conclusao: concluidoPor,
        concluido_por: concluidoPor,
        data_ref: dataRef,
        data_conclusao: String(r?.data_conclusao || r?.data || dataRef || '').slice(0, 10),
        detalhes: [{
          maquina: maquinaNome,
          qtd_perdida: qtdPerdida,
          operadores,
        }],
        toneladas_perdidas_item: toneladasPerdidasItem,
        toneladas_perdidas_calculavel: Number.isFinite(toneladasPerdidasItem) && toneladasPerdidasItem > 0,
      };
    });

    const empresaIdFiltro = String(req.query.empresa_id || '').trim();
    const maquinaFiltro = String(req.query.maquina || '').trim().toLowerCase();
    let enriquecidosFiltrados = enriquecidos.slice();
    if (empresaIdFiltro) {
      enriquecidosFiltrados = enriquecidosFiltrados.filter((r) => String(r?.empresa_id || r?.emp_id || '').trim() === empresaIdFiltro);
    }
    if (maquinaFiltro) {
      enriquecidosFiltrados = enriquecidosFiltrados.filter((r) => String(r?.maquina || '').trim().toLowerCase() === maquinaFiltro);
    }

    const totalCaixas = enriquecidosFiltrados.reduce((s, r) => s + (Number(r?.quantidade_perdida || 0) || 0), 0);
    const valorTotal = enriquecidosFiltrados.reduce((s, r) => s + (Number(r?.valor_perdido || 0) || 0), 0);
    const toneladasPerdidas = enriquecidosFiltrados.reduce((s, r) => s + (Number(r?.toneladas_perdidas_item || 0) || 0), 0);
    const toneladasSemDados = enriquecidosFiltrados.reduce((s, r) => s + ((r?.toneladas_perdidas_calculavel ? 0 : 1)), 0);

    const maqMap = Object.create(null);
    enriquecidosFiltrados.forEach((r) => {
      const m = String(r?.maquina || '—').trim() || '—';
      if (!maqMap[m]) maqMap[m] = { maquina: m, total_caixas: 0, valor_perdido: 0, ocorrencias: 0 };
      maqMap[m].total_caixas += Number(r?.quantidade_perdida || 0) || 0;
      maqMap[m].valor_perdido += Number(r?.valor_perdido || 0) || 0;
      maqMap[m].ocorrencias += 1;
    });
    const rankingMaquinas = Object.values(maqMap).sort((a, b) => b.total_caixas - a.total_caixas);

    const opMap = Object.create(null);
    enriquecidosFiltrados.forEach((r) => {
      const ops = Array.isArray(r?.operadores) && r.operadores.length
        ? r.operadores
        : ['Sem operador registrado'];
      ops.forEach((op) => {
        const nome = String(op || '').trim();
        if (!nome) return;
        if (!opMap[nome]) opMap[nome] = { operador: nome, total_caixas: 0, valor_perdido: 0, ocorrencias: 0 };
        opMap[nome].total_caixas += Number(r?.quantidade_perdida || 0) || 0;
        opMap[nome].valor_perdido += Number(r?.valor_perdido || 0) || 0;
        opMap[nome].ocorrencias += 1;
      });
    });
    const rankingOperadores = Object.values(opMap).sort((a, b) => {
      const aSem = String(a?.operador || '').trim() === 'Sem operador registrado';
      const bSem = String(b?.operador || '').trim() === 'Sem operador registrado';
      if (aSem !== bSem) return aSem ? 1 : -1;
      return (Number(b?.total_caixas || 0) || 0) - (Number(a?.total_caixas || 0) || 0);
    });

    const mesAnt = mes === 1 ? 12 : mes - 1;
    const anoAnt = mes === 1 ? ano - 1 : ano;
    const dadosAnt = filtrarPeriodo(todos || [], 'mes', mesAnt, anoAnt);
    const totalCaixasAnt = dadosAnt.reduce((s, r) => s + (Number(r?.quantidade ?? r?.caixas_perdidas ?? r?.qtd_perdida ?? 0) || 0), 0);
    const valorTotalAnt = dadosAnt.reduce((s, r) => {
      const qtd = Number(r?.quantidade ?? r?.caixas_perdidas ?? r?.qtd_perdida ?? 0) || 0;
      const valor = Number(r?.valor_perdido ?? ((Number(r?.valor_unitario ?? 0) || 0) * qtd) ?? 0) || 0;
      return s + valor;
    }, 0);

    return res.json({
      _debug: { tabelaAtiva, totalHistorico: todos?.length || 0, totalFiltrado: enriquecidosFiltrados.length, periodoSolicitado: requestedPeriodo, mesAplicado: mes, anoAplicado: ano, fallbackMesRecente },
      resumo_mes_atual: { total_caixas: totalCaixas, valor_total: valorTotal, total_ocorrencias: enriquecidosFiltrados.length, mes_referencia: String(ano) + '-' + String(mes).padStart(2, '0'), toneladas_perdidas: toneladasPerdidas, toneladas_sem_dados: toneladasSemDados },
      comparacao_mes_anterior: {
        total_caixas: totalCaixasAnt,
        valor_total: valorTotalAnt,
        variacao_caixas_pct: totalCaixasAnt > 0 ? parseFloat((((totalCaixas - totalCaixasAnt) / totalCaixasAnt) * 100).toFixed(1)) : null
      },
      ranking_maquinas: rankingMaquinas,
      ranking_operadores: rankingOperadores,
      detalhamento: enriquecidosFiltrados
    });
  } catch (e) {
    _debugRuntimeWrite({
      runId: 'pre-fix',
      hypothesisId: 'C',
      location: 'server.js:/api/caixas-perdidas/dashboard',
      msg: '[DEBUG] dashboard caixas perdidas erro',
      data: { error: String(e?.message || e) },
    });
    try { console.error('[CP DASHBOARD]', e.message); } catch (_) {}
    return res.status(500).json({ error: e.message, detalhamento: [] });
  }
});

app.get('/api/admin/corrigir_ofs_concluidas_sem_qtd', requireAdmin, async (req, res) => {
  try {
    const { data: ofs, error } = await supabase
      .from('ofs')
      .select('id,qtd,qtd_pedida,qtd_produzida,status')
      .in('status', ['Concluído', 'Concluido', 'Pedido Pronto'])
      .or('qtd.eq.0,qtd.is.null');
    if (error) return res.status(500).json({ ok: false, error: error.message || String(error) });

    let corrigidas = 0;
    for (const of of (ofs || [])) {
      const qtdAtual = Number(of?.qtd || 0) || 0;
      const qtdCorreta = Number(of?.qtd_pedida || of?.qtd_produzida || 0) || 0;
      if (qtdAtual === 0 && qtdCorreta > 0) {
        const { error: upErr } = await supabase
          .from('ofs')
          .update({ qtd: Math.trunc(qtdCorreta), qtd_produzida: Math.trunc(qtdCorreta) })
          .eq('id', of.id);
        if (!upErr) corrigidas++;
      }
    }
    return res.json({ ok: true, corrigidas });
  } catch (e) {
    return res.status(500).json({ ok: false, error: String(e.message || e) });
  }
});

async function _insertCaixaPerdidaCompat(input, req) {
  try { await _ensureCaixasPerdidasOperadorColumn(); } catch (_) {}
  const b = input || {};
  const hoje = new Date().toISOString().slice(0, 10);
  const mes = new Date().toISOString().slice(0, 7);
  const qtdPerdida = Math.trunc(Number(b.qtd_perdida ?? b.quantidade ?? b.caixas_perdidas ?? 0) || 0);
  const rawOperadores = Array.isArray(b.operadores)
    ? b.operadores
    : (typeof b.operadores === 'string'
        ? b.operadores.split(/[,;|]+/g)
        : [b.operador, b.operador_conclusao, b.operador_display, b.usuario_conclusao]);
  const operadores = Array.from(new Set(rawOperadores.map((op) => String(op || '').trim()).filter(Boolean)));
  const valorUnitario = Number(b.valor_unitario ?? b.vl_unit ?? 0) || 0;
  const valorPerdido = Number(b.valor_perdido ?? (qtdPerdida * valorUnitario) ?? 0) || 0;
  const payload = {
    of_id: b.of_id || null,
    of_numero: b.of_numero != null ? String(b.of_numero || '') : undefined,
    produto: String(b.produto || ''),
    cliente: String(b.cliente || b.cliente_nome || ''),
    cliente_nome: b.cliente_nome != null ? String(b.cliente_nome || b.cliente || '') : undefined,
    maquina: b.maquina != null ? String(b.maquina || b.maquina_nome || '') : undefined,
    maquina_nome: b.maquina_nome != null ? String(b.maquina_nome || b.maquina || '') : undefined,
    maquina_id: b.maquina_id != null ? String(b.maquina_id || '') : undefined,
    valor_unitario: valorUnitario,
    qtd_perdida: qtdPerdida,
    quantidade: qtdPerdida,
    valor_perdido: valorPerdido,
    data: b.data || b.data_conclusao || hoje,
    mes_referencia: b.mes_referencia || String((b.data || b.data_conclusao || mes)).slice(0, 7),
    emp_id: b.emp_id || '',
    usuario: b.usuario || req?.usuario?.nome || 'sistema',
    usuario_conclusao: b.usuario_conclusao || req?.usuario?.nome || 'sistema',
    obs: b.obs || '',
    operadores: operadores,
    operador: operadores[0] || (b.operador != null ? String(b.operador || '') : undefined),
    turno: b.turno != null ? String(b.turno || '') : undefined,
  };
  try { console.log('[CP INSERT COMPAT] payload:', JSON.stringify(payload)); } catch (_) {}
  ['of_numero', 'cliente_nome', 'maquina', 'maquina_nome', 'maquina_id', 'operadores', 'operador', 'turno'].forEach((key) => {
    if (Array.isArray(payload[key]) && payload[key].length) return;
    if (payload[key] == null || payload[key] === '') delete payload[key];
  });
  let currentPayload = { ...payload };
  _debugRuntimeWrite({
    runId: 'pre-fix',
    hypothesisId: 'C',
    location: 'server.js:_insertCaixaPerdidaCompat',
    msg: '[DEBUG] tentativa insert caixa perdida',
    data: {
      of_id: currentPayload.of_id || null,
      of_numero: currentPayload.of_numero || null,
      cliente: currentPayload.cliente || null,
      maquina: currentPayload.maquina || null,
      maquina_id: currentPayload.maquina_id || null,
      operadores: currentPayload.operadores || [],
      qtd_perdida: currentPayload.qtd_perdida || 0,
      valor_perdido: currentPayload.valor_perdido || 0,
      data: currentPayload.data || null,
    },
  });
  for (let i = 0; i < 12; i += 1) {
    const { data, error } = await supabase.from('caixas_perdidas').insert([currentPayload]).select().single();
    if (!error) {
      _debugRuntimeWrite({
        runId: 'pre-fix',
        hypothesisId: 'C',
        location: 'server.js:_insertCaixaPerdidaCompat',
        msg: '[DEBUG] insert caixa perdida sucesso',
        data: { id: data && data.id ? String(data.id) : null, of_numero: currentPayload.of_numero || null },
      });
      return { skipped: false, data };
    }
    const msg = String(error.message || error);
    const msgLower = msg.toLowerCase();
    _debugRuntimeWrite({
      runId: 'pre-fix',
      hypothesisId: 'C',
      location: 'server.js:_insertCaixaPerdidaCompat',
      msg: '[DEBUG] insert caixa perdida falhou',
      data: { error: msg, tentativa: i + 1, payloadKeys: Object.keys(currentPayload || {}) },
    });
    if (msgLower.includes('does not exist') || msgLower.includes('not exist') || msgLower.includes('not find') || msgLower.includes('not found')) {
      return { skipped: true, reason: 'table_missing' };
    }
    const m = msg.match(/column\s+"?([a-z0-9_]+)"?\s+(?:of relation .* )?does not exist/i)
      || msg.match(/Could not find the '([^']+)' column/i);
    const missingCol = m && m[1] ? String(m[1]).trim() : '';
    if (missingCol && Object.prototype.hasOwnProperty.call(currentPayload, missingCol)) {
      delete currentPayload[missingCol];
      continue;
    }
    if (msgLower.includes('column') && (msgLower.includes('maquina') || msgLower.includes('maquina_id') || msgLower.includes('operador') || msgLower.includes('turno') || msgLower.includes('quantidade') || msgLower.includes('of_numero') || msgLower.includes('cliente_nome'))) {
      ['maquina', 'maquina_nome', 'maquina_id', 'operadores', 'operador', 'turno', 'quantidade', 'of_numero', 'cliente_nome'].forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(currentPayload, key)) delete currentPayload[key];
      });
      continue;
    }
    throw error;
  }
  return { skipped: true, reason: 'insert_aborted' };
}

