async function _resolveEmpresaIdEstoqueByEmail(email) {
  const raw = String(email || '').trim().toLowerCase();
  if (!raw) throw new Error('email_nao_encontrado');
  const pseudoReq = { user: { email: raw }, usuario: { email: raw } };
  const empId = String((await resolverEmpresaId(pseudoReq)) || '').trim();
  if (!empId) throw new Error('empresa_id_nao_resolvido');
  return empId;
}

async function _queryByEmpresa(table, selectCols, empresa_id, orderCol, q) {
  const cols = ['empresa_id', 'emp_id', 'empId', 'empresa'];
  let lastErr = null;
  for (const col of cols) {
    let query = supabase.from(table).select(selectCols);
    if (empresa_id) query = query.eq(col, empresa_id);
    if (q) query = query.ilike('nome', `%${q}%`);
    if (orderCol) query = query.order(orderCol, { ascending: true });
    const { data, error } = await query;
    if (!error) return { data: data || [], col };
    lastErr = error;
    const msg = String(error?.message || error || '');
    if (msg.includes('column') || msg.includes('Could not find')) continue;
    throw error;
  }
  throw lastErr || new Error(`tabela ${table} indisponivel`);
}

async function _legacyListCompat(table, opts) {
  const empresaId = String(opts?.empresa_id || '').trim();
  const search = String(opts?.search || '').trim().toLowerCase();
  const limit = Math.max(1, Math.min(500, parseInt(String(opts?.limit || ''), 10) || 50));
  const searchCols = Array.isArray(opts?.searchCols) ? opts.searchCols : ['nome'];
  const sortCols = Array.isArray(opts?.sortCols) ? opts.sortCols : ['nome'];
  const variants = [
    { empresa: 'empresa_id', ativo: true },
    { empresa: 'empresa_id', ativo: false },
    { empresa: 'emp_id', ativo: true },
    { empresa: 'emp_id', ativo: false },
    { empresa: 'empId', ativo: false },
    { empresa: 'empresa', ativo: false },
    { empresa: null, ativo: false },
  ];
  let lastErr = null;
  for (const variant of variants) {
    try {
      let query = supabase.from(table).select('*').limit(Math.max(limit, 200));
      if (empresaId && variant.empresa) query = query.eq(variant.empresa, empresaId);
      if (variant.ativo) query = query.eq('ativo', true);
      const { data, error } = await query;
      if (error) {
        lastErr = error;
        const msg = String(error?.message || error || '').toLowerCase();
        if (
          msg.includes('does not exist') ||
          msg.includes('could not find the') ||
          msg.includes('column') ||
          msg.includes('relation')
        ) {
          continue;
        }
        throw error;
      }
      let rows = Array.isArray(data) ? data.slice() : [];
      if (search) {
        rows = rows.filter((row) => searchCols.some((col) => String(row?.[col] || '').toLowerCase().includes(search)));
      }
      rows.sort((a, b) => {
        for (const col of sortCols) {
          const av = String(a?.[col] || '').trim().toLowerCase();
          const bv = String(b?.[col] || '').trim().toLowerCase();
          const cmp = av.localeCompare(bv);
          if (cmp !== 0) return cmp;
        }
        return String(a?.id || '').localeCompare(String(b?.id || ''));
      });
      return rows.slice(0, limit);
    } catch (e) {
      lastErr = e;
      const msg = String(e?.message || e || '').toLowerCase();
      if (
        msg.includes('does not exist') ||
        msg.includes('could not find the') ||
        msg.includes('column') ||
        msg.includes('relation')
      ) {
        continue;
      }
      throw e;
    }
  }
  if (lastErr) {
    const msg = String(lastErr?.message || lastErr || '').toLowerCase();
    if (
      msg.includes('does not exist') ||
      msg.includes('could not find the') ||
      msg.includes('column') ||
      msg.includes('relation')
    ) {
      return [];
    }
  }
  return [];
}

async function _insertCompatTable(table, payload) {
  let cur = { ...(payload || {}) };
  let lastErr = null;
  for (let tentativa = 0; tentativa < 20; tentativa++) {
    const { data, error } = await supabase.from(table).insert([cur]).select();
    if (!error) return { data: Array.isArray(data) ? data[0] || null : data, error: null };
    lastErr = error;
    const msg = String(error.message || error || '');
    const m1 = msg.match(/Could not find the '([^']+)' column/i);
    const m2 = msg.match(/column\s+"([^"]+)"\s+does not exist/i);
    const col = (m1 && m1[1]) || (m2 && m2[1]) || null;
    if (col && Object.prototype.hasOwnProperty.call(cur, col)) {
      delete cur[col];
      continue;
    }
    break;
  }
  return { data: null, error: lastErr };
}

async function _updateCompatTable(table, id, payload) {
  let cur = { ...(payload || {}) };
  let lastErr = null;
  for (let tentativa = 0; tentativa < 20; tentativa++) {
    const { data, error } = await supabase.from(table).update(cur).eq('id', id).select();
    if (!error) return { data: Array.isArray(data) ? data[0] || null : data, error: null };
    lastErr = error;
    const msg = String(error.message || error || '');
    const m1 = msg.match(/Could not find the '([^']+)' column/i);
    const m2 = msg.match(/column\s+"([^"]+)"\s+does not exist/i);
    const col = (m1 && m1[1]) || (m2 && m2[1]) || null;
    if (col && Object.prototype.hasOwnProperty.call(cur, col)) {
      delete cur[col];
      continue;
    }
    break;
  }
  return { data: null, error: lastErr };
}

